/*
 * nuBuilder Next – end-to-end browser tests (0.8.361) against a running TEST installation with the sample application:
 *     NODE_PATH=$(npm root -g) BASE=http://127.0.0.1:8099/nunext/ DB="-unu -pnu nutest" PKG=../nunext.zip node dev/tests/e2e.js
 * Env: BASE (installation URL), DB (mysql / mysqldump arguments of its database – the suite saves the whole database first and puts it
 * back at the end, also when a test fails), ADMIN_USER / ADMIN_PW (globeadmin, default globeadmin / nu), USER_PW (password of the sample
 * users, default Test1234! – set by the suite for every sample user), PKG (a package for the update page check, optional),
 * ONLY (comma separated test names), KEEP=1 (do not restore the database), SITE (folder of the test installation: demo mode test).
 * Covers: login, form save / validation / change / clone / delete, sub-form rows, rights of access levels, audit trail and restore,
 * nuBuilder 4.9 compatibility (nub49_app, nub49_js), notifications, list views, start page favourites and list in 2 columns, CSV import, update package check, the self-test (developer mode), CSRF and the
 * include guards. Exit code 1 when a test fails. Never run it against a database with real data.
 */
const { chromium } = require('playwright');
const { execSync } = require('child_process');
const fs = require('fs'), os = require('os'), path = require('path');

const BASE = process.env.BASE || 'http://127.0.0.1:8099/nunext/';
const DB = process.env.DB || '-unu -pnu nutest';
const GA = [process.env.ADMIN_USER || 'globeadmin', process.env.ADMIN_PW || 'nu'];
const UPW = process.env.USER_PW || 'Test1234!';
const SITE = process.env.SITE || '';      // folder of the test installation (its nuconfig.php) – for the demo mode test
const ONLY = (process.env.ONLY || '').split(',').filter(Boolean);
const sql = q => execSync('mysql -N ' + DB, { input: q }).toString().trim();
const results = [];
let browser;

async function login(user, pw, opt = {}) {
	const ctx = await browser.newContext(Object.assign({ locale: 'en-GB', viewport: { width: 1300, height: 900 } }, opt));
	const p = await ctx.newPage();
	p.errors = [];
	p.on('pageerror', e => p.errors.push(e.message));
	p.on('dialog', d => d.accept());
	await p.goto(BASE + 'index.php?p=login');
	await p.fill('#username', user);
	await p.fill('#password', pw);
	await Promise.all([p.waitForLoadState('networkidle'), p.click('form button[type=submit]:not([name=demo_user])')]);
	for (let i = 0; i < 3 && await p.locator('.nuBellConfirm.show .btn-primary').count(); i++) { await p.click('.nuBellConfirm.show .btn-primary'); await p.waitForTimeout(500); }
	return p;
}
async function open(p, url) { const r = await p.goto(BASE + url); await p.waitForLoadState('networkidle'); return r; }
async function confirmDelete(p) {
	await p.waitForTimeout(400);
	if (await p.locator('#nuConfirm.show .js-confirm-ok').count()) await p.click('#nuConfirm.show .js-confirm-ok');   // own dialog (0.8.763)
	else if (await p.locator('.btn-red').count()) await p.click('.btn-red');
	await p.waitForLoadState('networkidle'); await p.waitForTimeout(600);
}
async function setField(p, sel, v) { await p.fill(sel, v); await p.locator(sel).dispatchEvent('change'); }
async function save(p) { await p.click('#nuSaveButton'); await p.waitForLoadState('networkidle'); await p.waitForTimeout(800); }
function expect(cond, msg) { if (!cond) throw new Error(msg); }

const T = {};      // name → async fn; run in this order

T.login_refused = async () => {
	const ctx = await browser.newContext(); const p = await ctx.newPage();
	await p.goto(BASE + 'index.php?p=login'); await p.fill('#username', GA[0]); await p.fill('#password', 'wrong-' + Date.now());
	await Promise.all([p.waitForNavigation({ waitUntil: 'load' }), p.click('form button[type=submit]:not([name=demo_user])')]);
	expect(/p=login/.test(p.url()) && await p.locator('.alert-danger, .alert-warning').count() > 0, 'wrong password not refused');
	sql("DELETE FROM zzzzsys_nunext_log WHERE event = 'login_failed'");
	await ctx.close();
};

T.form_insert = async (s) => {
	const p = s.ga;
	await open(p, 'index.php?p=form&f=samplecustomer&r=-1');
	await setField(p, '#cus_code', 'E2E1'); await setField(p, '#cus_name', 'E2E Customer');
	expect(await p.locator('#nuSaveButton.nuSaveEdited').count() === 1, 'Save button not red after a change');
	await save(p);
	s.cust = sql("SELECT sample_customer_id FROM sample_customer WHERE cus_code = 'E2E1'");
	expect(s.cust, 'record not saved');
};

T.form_required = async (s) => {
	const p = s.ga;
	await open(p, 'index.php?p=form&f=samplecustomer&r=-1');
	await setField(p, '#cus_code', 'E2E2'); await setField(p, '#cus_name', '');
	await p.click('#nuSaveButton'); await p.waitForTimeout(1200);
	expect(sql("SELECT COUNT(*) FROM sample_customer WHERE cus_code = 'E2E2'") === '0', 'saved without the required name');
	expect(await p.locator('.is-invalid, .nuValidationError, .jconfirm, .nuMessage, .alert-danger').count() > 0, 'no error shown');
};

T.form_unique = async (s) => {
	const p = s.ga;
	await open(p, 'index.php?p=form&f=samplecustomer&r=-1');
	await setField(p, '#cus_code', 'E2E1'); await setField(p, '#cus_name', 'Duplicate');
	await p.click('#nuSaveButton'); await p.waitForTimeout(1200);
	expect(sql("SELECT COUNT(*) FROM sample_customer WHERE cus_code = 'E2E1'") === '1', 'duplicate code saved');
};

T.form_update = async (s) => {
	const p = s.ga;
	await open(p, 'index.php?p=form&f=samplecustomer&r=' + s.cust);
	await setField(p, '#cus_name', 'E2E Customer changed');
	await save(p);
	expect(sql("SELECT cus_name FROM sample_customer WHERE sample_customer_id = '" + s.cust + "'") === 'E2E Customer changed', 'change not saved');
};

T.form_clone = async (s) => {
	const p = s.ga;
	await open(p, 'index.php?p=form&f=samplecustomer&r=' + s.cust);
	await p.evaluate(() => window.nuCloneAction()); await p.waitForLoadState('networkidle'); await p.waitForTimeout(600);
	await setField(p, '#cus_code', 'E2E3');
	await save(p);
	expect(sql("SELECT cus_name FROM sample_customer WHERE cus_code = 'E2E3'") === 'E2E Customer changed', 'clone not saved with the copied values');
};

// 0.8.680: Clone on nuBuilder Next's own record pages works as in nuBuilder Forte – the copy opens unsaved (badge, red Save), only Save writes it
T.record_clone = async (s) => {
	const p = s.ga;
	const tabs = ['zzzzsys_php', 'zzzzsys_access_php', 'zzzzsys_report', 'zzzzsys_access_report', 'zzzzsys_select', 'zzzzsys_select_clause', 'zzzzsys_permission_item',
		'zzzzsys_email_template', 'zzzzsys_file', 'zzzzsys_item', 'zzzzsys_prompt_generator', 'zzzzsys_cloner', 'zzzzsys_app_cloner'].filter(t => sql(`SHOW TABLES LIKE '${t}'`));
	const keep = path.join(os.tmpdir(), 'nunext-e2e-clone.sql');
	execSync('mysqldump ' + DB + ' ' + tabs.join(' ') + ' > ' + keep);
	try {
		sql("INSERT INTO zzzzsys_prompt_generator (zzzzsys_prompt_generator_id, pge_code, pge_description, pge_prompt, pge_template) VALUES ('e2e_pg', 'e2e_prompt', 'E2E prompt', 'Write a test', '0')");
		sql("INSERT INTO zzzzsys_cloner (zzzzsys_cloner_id, clo_form_source) VALUES ('e2e_cl', 'samplecustomer')");
		sql("INSERT INTO zzzzsys_app_cloner (zzzzsys_app_cloner_id, cla_code, cla_description, cla_target_db, cla_target_password) VALUES ('e2e_ac', 'e2e_app', 'E2E', 'nutest_cl', 'secret')");
		const cases = [
			['procedures', 'zzzzsys_php', 'zzzzsys_php_id', "zzzzsys_php_id NOT LIKE 'nu%' AND COALESCE(sph_system, '') <> '1'", 'sph_code'],
			['reports', 'zzzzsys_report', 'zzzzsys_report_id', '1 = 1', 'sre_layout'],
			['sqlbuilder', 'zzzzsys_select', 'zzzzsys_select_id', '1 = 1', 'sse_sql'],
			['permissions', 'zzzzsys_permission_item', 'zzzzsys_permission_item_id', '1 = 1', 'pme_description'],
			['emailtemplates', 'zzzzsys_email_template', 'zzzzsys_email_template_id', "COALESCE(emt_template, '0') <> '1'", 'emt_body'],
			['files', 'zzzzsys_file', 'zzzzsys_file_id', "zzzzsys_file_id NOT LIKE 'nu%'", 'sfi_json'],
			['items', 'zzzzsys_item', 'zzzzsys_item_id', '1 = 1', 'itm_value'],
			['prompts', 'zzzzsys_prompt_generator', 'zzzzsys_prompt_generator_id', '1 = 1', 'pge_prompt'],
			['cloner', 'zzzzsys_cloner', 'zzzzsys_cloner_id', '1 = 1', 'clo_form_source'],
			['appcloner', 'zzzzsys_app_cloner', 'zzzzsys_app_cloner_id', '1 = 1', 'cla_target_password'],
		];
		const done = [];
		for (const [route, t, pk, where, col] of cases) {
			if (!tabs.includes(t)) continue;
			const src = sql(`SELECT ${pk} FROM ${t} WHERE ${where} ORDER BY ${pk} LIMIT 1`);
			if (!src) continue;
			const n0 = +sql(`SELECT COUNT(*) FROM ${t}`);
			await open(p, `index.php?p=${route}&id=${src}`);
			const btn = p.locator('a.btn:has(.bi-copy)').first();
			expect(await btn.count() === 1, route + ': no Clone link');
			await Promise.all([p.waitForNavigation(), btn.click()]);
			await p.waitForLoadState('networkidle');
			expect(/clone=/.test(p.url()), route + ': Clone opened ' + p.url());
			expect(+sql(`SELECT COUNT(*) FROM ${t}`) === n0, route + ': Clone already saved a row');
			expect(await p.isVisible('.nuCloneBadge'), route + ': no badge');
			expect(await p.locator('.nuBtnSave.nuSaveEdited').count() > 0, route + ': Save not red');
			await Promise.all([p.waitForNavigation(), p.locator('[data-nu-save]').first().click()]);
			await p.waitForLoadState('networkidle');
			expect(+sql(`SELECT COUNT(*) FROM ${t}`) === n0 + 1, route + ': Save did not create the copy (' + p.url() + ')');
			const nid = new URL(p.url()).searchParams.get('id') || '';
			expect(nid !== '' && nid !== src && nid !== 'new', route + ': after Save ' + p.url());
			const same = sql(`SELECT COUNT(*) FROM ${t} a JOIN ${t} b ON b.${pk} = '${src}' WHERE a.${pk} = '${nid}' AND a.${col} <=> b.${col}`);
			if (route !== 'procedures') expect(same === '1', route + ': ' + col + ' not copied');
			expect(!(await p.isVisible('.nuCloneBadge')), route + ': badge after Save');
			done.push(route);
		}
		expect(done.length >= 8, 'cases run: ' + done.join(', '));
		// the user and access level pages opened copies unsaved before – now with the same badge and red Save
		const acc = sql("SELECT zzzzsys_access_id FROM zzzzsys_access ORDER BY zzzzsys_access_id LIMIT 1"), usr = sql("SELECT zzzzsys_user_id FROM zzzzsys_user WHERE sus_login_name LIKE 'sample_%' LIMIT 1");
		for (const u of [usr ? 'user&clone=' + usr : '', acc ? 'accesslevel&clone=' + acc : ''].filter(Boolean)) {
			await open(p, 'index.php?p=' + u);
			expect(await p.isVisible('.nuCloneBadge') && await p.locator('.nuBtnSave.nuSaveEdited').count() > 0, u + ': no badge / red Save');
		}
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		execSync('mysql ' + DB, { input: fs.readFileSync(keep) });
		fs.unlinkSync(keep);
	}
};

// 0.8.681: nuBrowseStyleBadge(column, rules, options) – colours, labels, icons by value (map or rule list), '$value', contrast, badge: false
T.browse_badge_rules = async (s) => {
	const p = s.ga;
	await open(p, 'index.php?p=form&f=samplecustomer');
	const r = await p.evaluate(() => {
		const cells = [...document.querySelectorAll('div.nuCell[data-nu-column="0"]')].filter(c => c.textContent.trim());
		if (cells.length < 3) return {skip: true};
		const v = cells.map(c => c.textContent.trim());
		cells[2].textContent = '#123456';
		nuBrowseStyleBadge(0, [
			{equals: v[0].toUpperCase(), ignoreCase: true, bg: 'rgb(255, 170, 170)', label: 'First', icon: 'star'},
			{contains: v[1], bg: '#FFF', color: 'nonsense-colour', border: '#000'},
			{test: (x, row) => x === '#123456' && row.length > 0, bg: '$value'},
			{default: true, badge: false}
		]);
		const b = (i) => cells[i].querySelector('.badge');
		return {
			first: b(0) && b(0).style.backgroundColor === 'rgb(255, 170, 170)' && /First/.test(b(0).textContent) && !!b(0).querySelector('.bi-star') && b(0).title === v[0] && b(0).style.color === 'rgb(33, 37, 41)',
			second: b(1) && b(1).style.backgroundColor === 'rgb(255, 255, 255)' && b(1).style.color === 'rgb(33, 37, 41)' && /solid/.test(b(1).style.border) && b(1).textContent === v[1],
			third: b(2) && b(2).style.backgroundColor === 'rgb(18, 52, 86)' && b(2).style.color === 'rgb(255, 255, 255)',
			plain: cells.slice(3).every(c => !c.querySelector('.badge')),
			map: (() => { const c = document.querySelector('div.nuCell[data-nu-column="1"]'); if (!c) return true; const t = c.textContent.trim();
				nuBrowseStyleBadge([1], {[t]: '#000'}); const x = c.querySelector('.badge'); return !!x && x.style.color === 'rgb(255, 255, 255)'; })(),
		};
	});
	if (r.skip) { s.skip = 'fewer than 3 customers'; return; }
	expect(r.first && r.second && r.third && r.plain && r.map, JSON.stringify(r));
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
};

// 0.8.683: access levels of a form from the form's ⋮ menu and from design mode (pages/nuformaccess.php, assets/js/nu/nuformaccess.js)
T.form_access_dialog = async (s) => {
	const p = s.ga, keep = path.join(os.tmpdir(), 'nunext-e2e-fac.sql');
	const has = () => sql("SELECT CONCAT(slf_print_button, slf_save_button) FROM zzzzsys_access_form WHERE slf_zzzzsys_form_id = 'samplecustomer' AND slf_zzzzsys_access_id = 'sample_viewer'");
	if (!sql("SELECT COUNT(*) FROM zzzzsys_access WHERE zzzzsys_access_id = 'sample_viewer'")) { s.skip = 'no sample levels'; return; }
	execSync('mysqldump ' + DB + ' zzzzsys_access_form > ' + keep);
	try {
		const dlg = async () => { await p.waitForSelector('#nuFormAccessDlg.show'); await p.waitForTimeout(300); return p.locator('#nuFacTable tbody tr[data-level="sample_viewer"]'); };
		await open(p, 'index.php?p=form&f=samplecustomer');
		await p.click('#nuOptions'); await p.click('.nuOptionsList .dropdown-item:has(.bi-people)');
		let row = await dlg();
		expect(await p.locator('#nuFacTable tbody tr').count() >= 5 && await p.isDisabled('#nuFacSave'), 'dialog / Save before a change');
		// 0.8.696: sortable columns – level code ascending / descending, Open = ticked first
		const codes = () => p.$$eval('#nuFacTable tbody tr', trs => trs.map(t => t.getAttribute('data-level')));
		await p.click('#nuFacTable th[data-sort=level] button'); const asc = await codes();
		await p.click('#nuFacTable th[data-sort=level] button'); const desc = await codes();
		expect(asc.join() === [...asc].sort((x, y) => x.localeCompare(y, undefined, { sensitivity: 'base', numeric: true })).join() && desc.join() === [...asc].reverse().join()
			&& await p.getAttribute('#nuFacTable th[data-sort=level]', 'aria-sort') === 'descending', 'sort by level: ' + asc.join(','));
		await p.click('#nuFacTable th[data-sort=open] button');
		const ons = await p.$$eval('#nuFacTable tbody tr .nuFacOpen', c => c.map(x => x.checked ? 1 : 0));
		expect(ons.join() === [...ons].sort((x, y) => y - x).join() && await p.isDisabled('#nuFacSave'), 'sort by Open: ' + ons.join(''));
		await row.locator('.nuFacOpen').uncheck();
		expect(await row.locator('.nuFacRight').first().isDisabled(), 'buttons of a level without the form');
		await p.click('#nuFacSave'); await p.waitForSelector('#nuFormAccessDlg', { state: 'detached' });
		expect(has() === '', 'level kept the form');
		// design mode: Tools → Access levels, the level gets the form back with Print only
		await open(p, 'index.php?p=form&f=samplecustomer&r=-1&design=1');
		await p.click('#nuDsFormAccess');
		row = await dlg();
		await row.locator('.nuFacOpen').check();
		expect(!(await row.locator('.nuFacRight[data-right=save]').isChecked()), 'buttons ticked by themselves');
		await row.locator('.nuFacRight[data-right=print]').check();
		await p.fill('#nuFacSearch', 'zzz-none'); expect(await row.isHidden(), 'search');
		await p.fill('#nuFacSearch', '');
		await p.click('#nuFacSave'); await p.waitForSelector('#nuFormAccessDlg', { state: 'detached' });
		expect(has() === '10', 'level rights after design mode: ' + has());
		expect(/sample_viewer/.test(sql("SELECT details FROM zzzzsys_nunext_log WHERE event = 'access_form_rights' ORDER BY log_time DESC LIMIT 1")), 'log');
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
		// a user without the access level form: no menu entry, the route refuses
		const u = await login('sample_ben', UPW);
		await open(u, 'index.php?p=form&f=samplecustomer');
		const st = await u.evaluate(async () => (await fetch('index.php?p=formaccess&f=samplecustomer')).status);
		expect(st === 403 && await u.locator('.nuOptionsList .dropdown-item:has(.bi-people)').count() === 0, 'user without the right: ' + st);
		await u.context().close();
	} finally {
		execSync('mysql ' + DB, { input: fs.readFileSync(keep) }); fs.unlinkSync(keep);
	}
};

// 0.8.697: dashboard form – Access levels on their own tab with a group filter and a ticked count; Save stays on the tab; the
// description is saved (its field name did not match before)
T.dashboard_access_tab = async (s) => {
	const p = s.ga, keep = path.join(os.tmpdir(), 'nunext-e2e-dash.sql');
	if (!sql("SELECT COUNT(*) FROM zzzzsys_nunext_dashboard WHERE zzzzsys_nunext_dashboard_id = 'sample_dash_sales'")) { s.skip = 'no sample dashboard'; return; }
	execSync('mysqldump ' + DB + ' zzzzsys_nunext_dashboard > ' + keep);
	try {
		await open(p, 'index.php?p=dashboards&id=sample_dash_sales');
		expect(await p.isVisible('#dCode') && !(await p.isVisible('.dashAccessList')), 'General tab first');
		await p.click('#dashTabAccessBtn'); await p.waitForTimeout(300);
		const vis = () => p.$$eval('.dashAccessList [data-group]', e => e.filter(x => !x.hidden).map(x => x.getAttribute('data-group')));
		const all = await vis();
		await p.selectOption('#dAccGroup', 'tkt');
		const tkt = await vis();
		expect(all.length > tkt.length && tkt.length > 0 && tkt.every(g => g === 'tkt'), 'group filter: ' + tkt.join(','));
		await p.selectOption('#dAccGroup', '*');
		const before = await p.textContent('#dAccCount'), box = p.locator('.dashAccessList input[name="access[]"]:not(:checked)').first();
		await box.check();
		const after = await p.textContent('#dAccCount');
		expect(parseInt(after, 10) === parseInt(before, 10) + 1, 'count: ' + before + ' → ' + after);
		await p.click('#dashTabGeneralBtn'); await p.fill('#dDesc', 'e2e description');
		await p.click('#dashTabAccessBtn');
		await Promise.all([p.waitForNavigation(), p.click('#dashSave')]);
		expect(/tab=access/.test(p.url()) && await p.isVisible('.dashAccessList'), 'stays on the tab: ' + p.url());
		expect(sql("SELECT description FROM zzzzsys_nunext_dashboard WHERE zzzzsys_nunext_dashboard_id = 'sample_dash_sales'") === 'e2e description', 'description saved');
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		execSync('mysql ' + DB, { input: fs.readFileSync(keep) }); fs.unlinkSync(keep);
	}
};

// 0.8.698: integrity check of the database – Update → System → Check the database, the package check (problems need the tick,
// the server refuses the install without it), php nucron.php integrity (exit code 1 on problems)
T.integrity = async (s) => {
	const p = s.ga, keep = path.join(os.tmpdir(), 'nunext-e2e-ic.sql');
	execSync('mysqldump ' + DB + ' zzzzsys_user zzzzsys_object > ' + keep);
	try {
		sql(`INSERT INTO zzzzsys_user (zzzzsys_user_id, sus_login_name, sus_name, sus_json) VALUES ('e2e_ic_u1', 'e2e_ic_dup', 'IC 1', '{bad'), ('e2e_ic_u2', 'e2e_ic_dup', 'IC 2', NULL);
			INSERT INTO zzzzsys_object (zzzzsys_object_id, sob_all_zzzzsys_form_id, sob_all_id, sob_all_type) VALUES ('e2e_ic_o1', 'e2e_no_form', 'x', 'input');
			INSERT INTO zzzzsys_nunext_migration (zzzzsys_nunext_migration_id) VALUES ('9999-e2e-future')`);
		await open(p, 'index.php?p=update&tab=system&integrity=1');
		if (/p=reauth/.test(p.url())) { await p.fill('#reauthPassword', GA[1]); await Promise.all([p.waitForLoadState('networkidle'), p.click('button[type=submit]')]); await open(p, 'index.php?p=update&tab=system&integrity=1'); }
		const ids = await p.$$eval('#updIntegrityNow [data-ic]', e => e.map(x => x.getAttribute('data-ic') + ':' + x.getAttribute('data-level')));
		for (const want of ['dup_login:error', 'json:warn', 'orphans:warn', 'migration_newer:warn']) expect(ids.includes(want), 'missing ' + want + ': ' + ids.join(','));
		expect(/e2e_ic_dup/.test(await p.textContent('[data-ic=dup_login]')) && /e2e_ic_o1/.test(await p.textContent('[data-ic=orphans]')), 'details');
		expect(sql("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'zzzzsys_nunext_ichk'") === '0', 'scratch table dropped');
		if (SITE) {
			let code = 0;
			try { execSync('php nucron.php integrity', { cwd: SITE, stdio: 'pipe' }); } catch (e) { code = e.status; }
			expect(code === 1, 'nucron.php integrity exit code: ' + code);
		}
		const pkg = process.env.PKG;
		if (pkg && fs.existsSync(pkg)) {
			await open(p, 'index.php?p=update');
			if (!(await p.locator('#updOther').isVisible())) { await p.click('#updOtherBtn'); await p.waitForTimeout(500); }
			await p.setInputFiles('#updPackage', pkg);
			await Promise.all([p.waitForLoadState('networkidle'), p.click('#updUpload')]);
			await p.waitForTimeout(500);
			const pk = await p.$$eval('#updIntegrity [data-ic]', e => e.map(x => x.getAttribute('data-ic') + ':' + x.getAttribute('data-level')));
			expect(pk.includes('dup_login:error') && pk.includes('migration_newer:error'), 'package check: ' + pk.join(','));
			expect(await p.getAttribute('#nuIcAck', 'form') === 'updInstallForm' && await p.evaluate(() => document.getElementById('nuIcAck').required), 'tick needed');
			// the server refuses without the tick (reinstall set, so only the integrity check can stop it)
			const txt = await p.evaluate(async () => { const f = document.getElementById('updInstallForm'), fd = new FormData(f); fd.delete('integrity_ack'); fd.set('reinstall', '1');
				return (await fetch(f.getAttribute('action'), { method: 'POST', body: fd })).text(); });
			const msgs = ['en', 'de'].map(l => (fs.readFileSync(path.resolve(__dirname, '../../lang/' + l + '.php'), 'utf8').match(/'ic_ack_needed' => '((?:[^'\\]|\\.)*)'/) || [])[1]).filter(Boolean)
				.map(m => m.replace(/\\'/g, "'").replace(/"/g, '&quot;').slice(0, 40));
			expect(msgs.some(m => txt.includes(m)), 'install refused without the tick');
			expect(sql("SELECT COUNT(*) FROM zzzzsys_nunext_log WHERE event = 'integrity_ignored'") === '0', 'not installed');
			await open(p, 'index.php?p=update');
			if (await p.locator('#updCancel').count()) await Promise.all([p.waitForLoadState('networkidle'), p.click('#updCancel')]);
		}
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		execSync('mysql ' + DB, { input: fs.readFileSync(keep) }); fs.unlinkSync(keep);
		sql("DELETE FROM zzzzsys_nunext_migration WHERE zzzzsys_nunext_migration_id = '9999-e2e-future'");
	}
};

