		const h2 = await p.evaluate(() => document.querySelector('.nuLvMore').previousElementSibling.clientHeight);
		expect(h2 > h1 * 2 && /p=log/.test(p.url()), 'more did not unfold: ' + h1 + ' / ' + h2);
