// 0.8.663: New form in three steps (Form · Table and fields · Layout and access); Next checks each step; the form opens in design mode
T.new_form_pick = async (s) => {                        // 0.8.675: New form on an existing table – chosen columns, own labels, list columns, order
	const p = s.ga, code = 'e2ePick' + Date.now().toString(36);
	let id = '';
	try {
		await open(p, 'index.php?p=builder&new=1&start=wizard');
		await p.fill('#nb_desc', 'E2E pick'); await p.fill('#nb_code', code);
		await p.click('#nbStepNext'); await p.waitForTimeout(200);
		await p.waitForFunction(() => document.querySelector('#nb_table option[value="sample_customer"]'));
		await p.evaluate(() => { const x = document.getElementById('nb_table'); if (x.tomselect) x.tomselect.setValue('sample_customer'); else { x.value = 'sample_customer'; x.dispatchEvent(new Event('change')); } });
		await p.waitForSelector('#nbPickRows tr[data-name="cus_notes"]', { state: 'attached' });
		expect(await p.isVisible('#nbPickWrap') && !(await p.isVisible('#nbPickRows')), 'column list not folded');
		expect(/10 of 10/.test(await p.locator('#nbPickCount').textContent()), 'count: ' + await p.locator('#nbPickCount').textContent());
		await p.click('#nbPickBtn'); await p.waitForTimeout(400);
		const row = (n) => p.locator(`#nbPickRows tr[data-name="${n}"]`);
		await row('cus_email').locator('.nbPickOn').uncheck(); await row('cus_notes').locator('.nbPickOn').uncheck();
		await row('cus_name').locator('.nbPickUp').click();
		await row('cus_phone').locator('.nbPickLabel').fill('Telefon');
		await row('cus_code').locator('.nbPickList').uncheck();
		expect(await row('cus_code').locator('.nbPickFlt').isDisabled(), 'filter box of a column not in the list enabled');
		await row('cus_phone').locator('.nbPickFlt').check();   // 0.8.688: column filter of the list
		await row('cus_since').locator('.nbPickLabel').focus(); await p.keyboard.press('Alt+ArrowUp');
		expect(await row('cus_email').locator('.nbPickList').isDisabled(), 'list box of an unticked column enabled');
		const order = await p.$$eval('#nbPickRows tr', (r) => r.map((x) => x.getAttribute('data-name')));
		expect(order.indexOf('cus_name') < order.indexOf('cus_code') && order.indexOf('cus_since') < order.indexOf('cus_active'), 'order: ' + order.join(','));
		await p.click('#nbStepNext'); await p.waitForTimeout(200);
		await Promise.all([p.waitForURL(/design=1/), p.click('#nbCreate')]);
		id = sql(`SELECT zzzzsys_form_id FROM zzzzsys_form WHERE sfo_code = '${code}'`);
		const objs = sql(`SELECT GROUP_CONCAT(sob_all_id ORDER BY sob_all_order SEPARATOR ',') FROM zzzzsys_object WHERE sob_all_zzzzsys_form_id = '${id}'`).split(',');
		const want = order.filter((n) => n !== 'cus_email' && n !== 'cus_notes');
		expect(objs.join(',') === want.join(','), 'objects: ' + objs.join(',') + ' / ' + want.join(','));
		expect(sql(`SELECT sob_all_label FROM zzzzsys_object WHERE sob_all_zzzzsys_form_id = '${id}' AND sob_all_id = 'cus_phone'`) === 'Telefon', 'own label not used');
		const br = sql(`SELECT GROUP_CONCAT(sbr_display ORDER BY sbr_order SEPARATOR ',') FROM zzzzsys_browse WHERE sbr_zzzzsys_form_id = '${id}'`).split(',');
		expect(br.indexOf('cus_code') < 0 && br.indexOf('cus_email') < 0 && br[0] === want.filter((n) => n !== 'cus_code')[0], 'list columns: ' + br.join(','));
		expect(/"filter":true/.test(sql(`SELECT sbr_json FROM zzzzsys_browse WHERE sbr_zzzzsys_form_id = '${id}' AND sbr_display = 'cus_phone'`))
			&& sql(`SELECT COUNT(*) FROM zzzzsys_browse WHERE sbr_zzzzsys_form_id = '${id}' AND sbr_display <> 'cus_phone' AND sbr_json LIKE '%filter%'`) === '0', 'list filter of cus_phone');
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		if (!id) id = sql(`SELECT zzzzsys_form_id FROM zzzzsys_form WHERE sfo_code = '${code}'`);
		if (id) {
			sql(`DELETE FROM zzzzsys_object WHERE sob_all_zzzzsys_form_id = '${id}'`); sql(`DELETE FROM zzzzsys_tab WHERE syt_zzzzsys_form_id = '${id}'`);
			sql(`DELETE FROM zzzzsys_browse WHERE sbr_zzzzsys_form_id = '${id}'`); sql(`DELETE FROM zzzzsys_access_form WHERE slf_zzzzsys_form_id = '${id}'`);
			sql(`DELETE FROM zzzzsys_php WHERE zzzzsys_php_id LIKE '${id}%'`); sql(`DELETE FROM zzzzsys_nunext_form_draft WHERE form_id = '${id}'`); sql(`DELETE FROM zzzzsys_form WHERE zzzzsys_form_id = '${id}'`);
		}
	}
};

T.new_form_view = async (s) => {                        // 0.8.721: New form on a view – marked "(view)", key column suggested, read-only view → Browse
	const p = s.ga, code = 'e2eView' + Date.now().toString(36);
	let id = '';
	const pickT = (t) => p.evaluate((v) => { const x = document.getElementById('nb_table'); if (x.tomselect) x.tomselect.setValue(v); else { x.value = v; x.dispatchEvent(new Event('change')); } }, t);
	try {
		sql('CREATE OR REPLACE VIEW e2e_vw_cust AS SELECT sample_customer_id, cus_code, cus_name FROM sample_customer');
		sql('CREATE OR REPLACE VIEW e2e_vw_cnt AS SELECT cus_country, COUNT(*) AS n FROM sample_customer GROUP BY cus_country');
		sql('CREATE OR REPLACE VIEW e2e_vw_dup AS SELECT ord_sample_customer_id, ord_total FROM sample_order');
		await open(p, 'index.php?p=builder&new=1&start=wizard');
		await p.fill('#nb_desc', 'E2E view'); await p.fill('#nb_code', code);
		await p.click('#nbStepNext'); await p.waitForTimeout(200);
		await p.waitForFunction(() => document.querySelector('#nb_table option[value="e2e_vw_cnt"]'));
		const lbl = await p.$eval('#nb_table option[value="e2e_vw_cnt"]', (o) => o.textContent);
		const tlbl = await p.$eval('#nb_table option[value="sample_customer"]', (o) => o.textContent);
		const grp = await p.$eval('#nb_table option[value="e2e_vw_cnt"]', (o) => o.parentElement.tagName === 'OPTGROUP' ? o.parentElement.label : '');
		const tgrp = await p.$eval('#nb_table option[value="sample_customer"]', (o) => o.parentElement.tagName === 'OPTGROUP' ? o.parentElement.label : '');
		expect(lbl === 'e2e_vw_cnt' && tlbl === 'sample_customer' && grp !== '' && tgrp !== '' && grp !== tgrp, 'groups (0.8.851): ' + lbl + ' in ' + grp + ' / ' + tlbl + ' in ' + tgrp);
		await pickT('e2e_vw_cnt');
		await p.waitForSelector('#nbViewInfo:not([hidden])');
		expect(await p.$eval('#nb_type', (x) => x.value) === 'browse', 'type not set to Browse');
		expect(await p.$eval('#nbViewInfo', (x) => x.classList.contains('alert-warning') && /cannot save/.test(x.textContent)), 'read-only notice: ' + await p.textContent('#nbViewInfo'));
		expect(await p.$eval('#nb_pk', (x) => x.value) === 'cus_country', 'key of the GROUP BY view');
		await p.evaluate(() => { const x = document.getElementById('nb_type'); x.value = 'browseedit'; x.dispatchEvent(new Event('change')); });   // step 1 is hidden now
		await pickT('e2e_vw_dup');
		await p.waitForFunction(() => /ord_sample_customer_id/.test(document.getElementById('nbViewInfo').textContent));
		expect(await p.$eval('#nbViewInfo', (x) => /repeated or empty/.test(x.textContent) && x.classList.contains('alert-warning')), 'duplicate key warning: ' + await p.textContent('#nbViewInfo'));
		expect(await p.$eval('#nb_type', (x) => x.value) === 'browseedit', 'type changed for an updatable view');
		await pickT('e2e_vw_cust');
		await p.waitForFunction(() => /sample_customer_id/.test(document.getElementById('nbViewInfo').textContent));
		expect(await p.$eval('#nbViewInfo', (x) => x.classList.contains('alert-info') && /can save/.test(x.textContent)), 'updatable notice: ' + await p.textContent('#nbViewInfo'));
		expect(await p.$eval('#nb_pk', (x) => x.value) === 'sample_customer_id', 'suggested key');
		await pickT('sample_customer');
		await p.waitForTimeout(600);
		expect(await p.$eval('#nbViewInfo', (x) => x.hidden), 'notice stays for a table');
		await pickT('e2e_vw_cust');
		await p.waitForFunction(() => document.getElementById('nb_pk').value === 'sample_customer_id');
		await p.click('#nbStepNext'); await p.waitForTimeout(200);
		await Promise.all([p.waitForURL(/design=1/), p.click('#nbCreate')]);
		id = sql(`SELECT zzzzsys_form_id FROM zzzzsys_form WHERE sfo_code = '${code}'`);
		expect(sql(`SELECT CONCAT(sfo_table, '|', sfo_primary_key, '|', sfo_type) FROM zzzzsys_form WHERE zzzzsys_form_id = '${id}'`) === 'e2e_vw_cust|sample_customer_id|browseedit', 'form row');
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		if (!id) id = sql(`SELECT zzzzsys_form_id FROM zzzzsys_form WHERE sfo_code = '${code}'`);
		if (id) {
			sql(`DELETE FROM zzzzsys_object WHERE sob_all_zzzzsys_form_id = '${id}'`); sql(`DELETE FROM zzzzsys_tab WHERE syt_zzzzsys_form_id = '${id}'`);
			sql(`DELETE FROM zzzzsys_browse WHERE sbr_zzzzsys_form_id = '${id}'`); sql(`DELETE FROM zzzzsys_access_form WHERE slf_zzzzsys_form_id = '${id}'`);
			sql(`DELETE FROM zzzzsys_php WHERE zzzzsys_php_id LIKE '${id}%'`); sql(`DELETE FROM zzzzsys_nunext_form_draft WHERE form_id = '${id}'`); sql(`DELETE FROM zzzzsys_form WHERE zzzzsys_form_id = '${id}'`);
		}
		sql('DROP VIEW IF EXISTS e2e_vw_cust, e2e_vw_cnt, e2e_vw_dup');
	}
};

// 0.8.877: passkeys with Chrome's virtual authenticator (the site as localhost – browsers refuse passkeys for IP addresses): add one
// under Security, use it as the second factor, sign in without a password (button; the user name field offers it too), the admin's
// view on the user form, remove it; on 127.0.0.1 the card explains why passkeys cannot be used
T.passkeys = async (s) => {
	if (!SITE || !fs.existsSync(path.join(SITE, 'nuconfig.php'))) { s.skip = 'SITE not set'; return; }
	if (!/127\.0\.0\.1|localhost/.test(BASE)) { s.skip = 'BASE is not local'; return; }
	const LB = BASE.replace('127.0.0.1', 'localhost');
	const anna = sql("SELECT zzzzsys_user_id FROM zzzzsys_user WHERE sus_login_name = 'sample_anna'");
	if (!anna) { s.skip = 'no sample users'; return; }
	const acc = sql(`SELECT sus_zzzzsys_access_id FROM zzzzsys_user WHERE zzzzsys_user_id = '${anna}'`);
	const use2fa = sql(`SELECT IFNULL(sal_use_2fa, '') FROM zzzzsys_access WHERE zzzzsys_access_id = '${acc}'`);
	const cfg = path.join(SITE, 'nuconfig.php'), orig = fs.readFileSync(cfg, 'utf8');
	const secRow = sql("SELECT setting_value FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'security'");
	const setSec = (o) => { const v = Object.assign(JSON.parse(secRow || '{}'), o); sql(`REPLACE INTO zzzzsys_nunext_setting (zzzzsys_nunext_setting_id, setting_value) VALUES ('security', '${JSON.stringify(v)}')`); };
	const ctx = await browser.newContext({ locale: 'en-GB', viewport: { width: 1200, height: 900 } });
	const p = await ctx.newPage();
	p.errors = [];
	p.on('pageerror', e => p.errors.push(e.message));
	p.on('dialog', d => d.accept());
	const cdp = await ctx.newCDPSession(p);
	await cdp.send('WebAuthn.enable');
	const { authenticatorId } = await cdp.send('WebAuthn.addVirtualAuthenticator', { options: { protocol: 'ctap2', transport: 'internal',
		hasResidentKey: true, hasUserVerification: true, isUserVerified: true, automaticPresenceSimulation: true } });
	const pwLogin = async () => {
		await p.goto(LB + 'index.php?p=login'); await p.waitForLoadState('networkidle');
		await p.fill('#username', 'sample_anna'); await p.fill('#password', UPW);
		await Promise.all([p.waitForNavigation(), p.click('form button[type=submit]:not([name=demo_user])')]);
	};
	sql("DELETE FROM zzzzsys_nunext_log WHERE event = 'login_failed'");
	try {
		sql(`DELETE FROM zzzzsys_nunext_passkey WHERE user_id = '${anna}'`);
		// add a passkey under Security
		await pwLogin();
		expect(/p=home/.test(p.url()), 'password sign-in: ' + p.url());
		await p.goto(LB + 'index.php?p=security'); await p.waitForLoadState('networkidle');
		expect(await p.locator('#secPasskeys #nuPkAdd').count() === 1, 'Add a passkey on the security page');
		await p.fill('#pkName', 'E2E key');
		await Promise.all([p.waitForNavigation(), p.click('#nuPkAdd')]);
		await p.waitForLoadState('networkidle');
		expect(await p.locator('#secPkList li').count() === 1 && /E2E key/.test(await p.textContent('#secPkList')), 'passkey listed');
		const row = sql(`SELECT CONCAT(name, '|', alg, '|', sign_count) FROM zzzzsys_nunext_passkey WHERE user_id = '${anna}'`);
		expect(/^E2E key\|-7\|\d+$/.test(row), 'stored: ' + row);
		// second factor: the access level asks for 2FA → the passkey is offered first
		sql(`UPDATE zzzzsys_access SET sal_use_2fa = '1' WHERE zzzzsys_access_id = '${acc}'`);
		fs.writeFileSync(cfg, orig.replace(/\?>\s*$/, '') + '\n$nuConfig2FAUser = true;\n');
		await new Promise(r => setTimeout(r, 3500));                // OPcache checks the file every 2 s
		await ctx.clearCookies();
		await pwLogin();
		expect(/p=twofa/.test(p.url()) && await p.locator('#nuPk2fa').count() === 1, 'second factor page with the passkey: ' + p.url());
		await Promise.all([p.waitForNavigation(), p.click('#nuPk2fa')]);
		expect(/p=home/.test(p.url()), 'signed in with the passkey as second factor: ' + p.url());
		expect(/"2fa":"passkey"/.test(sql(`SELECT details FROM zzzzsys_nunext_log WHERE event = 'login' AND user_id = '${anna}' ORDER BY log_time DESC LIMIT 1`)), 'log: 2fa passkey');
		fs.writeFileSync(cfg, orig);
		sql(`UPDATE zzzzsys_access SET sal_use_2fa = '${use2fa}' WHERE zzzzsys_access_id = '${acc}'`);
		await new Promise(r => setTimeout(r, 3500));
		// without a password: the button (the offer in the user name field waits while the authenticator needs a touch)
		setSec({ passkey_login: true });
		await ctx.clearCookies();
		await cdp.send('WebAuthn.setAutomaticPresenceSimulation', { authenticatorId, enabled: false });
		await p.goto(LB + 'index.php?p=login'); await p.waitForLoadState('networkidle');
		expect(await p.locator('#nuPkLogin').count() === 1 && /webauthn/.test(await p.getAttribute('#username', 'autocomplete')), 'passkey sign-in offered');
		const before = +sql(`SELECT sign_count FROM zzzzsys_nunext_passkey WHERE user_id = '${anna}'`);
		await cdp.send('WebAuthn.setAutomaticPresenceSimulation', { authenticatorId, enabled: true });
		await Promise.all([p.waitForNavigation({ timeout: 15000 }), p.click('#nuPkLogin')]);
		expect(/p=home/.test(p.url()), 'signed in without a password: ' + p.url());
		expect(/"via":"passkey"/.test(sql(`SELECT details FROM zzzzsys_nunext_log WHERE event = 'login' AND user_id = '${anna}' ORDER BY log_time DESC LIMIT 1`)), 'log: via passkey');
		expect(+sql(`SELECT sign_count FROM zzzzsys_nunext_passkey WHERE user_id = '${anna}'`) > before, 'counter went up');
		// the admin sees it on the user form
		await open(s.ga, 'index.php?p=user&id=' + anna);
		expect(await s.ga.locator('#userPasskeys li').count() === 1, 'user form lists the passkey');
		// 127.0.0.1: no passkeys (browsers refuse IP addresses) – the card says why
		await open(s.ga, 'index.php?p=security');
		expect(await s.ga.locator('#secPkProblem').count() === 1 && await s.ga.locator('#nuPkAdd').count() === 0, 'IP address: passkeys explained, no Add');
		// remove it
		await p.goto(LB + 'index.php?p=security'); await p.waitForLoadState('networkidle');
		await p.click('#secPkList form button[type=submit]');
		await p.waitForTimeout(400);
		if (await p.locator('#nuConfirm.show .js-confirm-ok').count()) await Promise.all([p.waitForNavigation(), p.click('#nuConfirm.show .js-confirm-ok')]);
		await p.waitForLoadState('networkidle');
		expect(sql(`SELECT COUNT(*) FROM zzzzsys_nunext_passkey WHERE user_id = '${anna}'`) === '0', 'passkey removed');
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		fs.writeFileSync(cfg, orig);
		sql(`UPDATE zzzzsys_access SET sal_use_2fa = '${use2fa}' WHERE zzzzsys_access_id = '${acc}'`);
		if (secRow) sql(`REPLACE INTO zzzzsys_nunext_setting (zzzzsys_nunext_setting_id, setting_value) VALUES ('security', '${secRow.replace(/'/g, "''")}')`);
		else sql("DELETE FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'security'");
		sql(`DELETE FROM zzzzsys_nunext_passkey WHERE user_id = '${anna}'`);
		await ctx.close();
		await new Promise(r => setTimeout(r, 2500));
	}
};

// single sign-on (0.8.863): settings, Test sign-in, button on the sign-in page, existing user, refusals (no user, bad signature,
// unverified e-mail, provider error, foreign state), new user by the group map, "SSO only" refuses the password – fake provider dev/tests/fakeoidc.py
T.sso_login = async (s) => {
	const p = s.ga, anna = 'sample_anna', port = 3100 + Math.floor(Math.random() * 400), iss = 'http://127.0.0.1:' + port;
	const olog = path.join(os.tmpdir(), 'e2e-oidc-' + Date.now() + '.log');
	const lvl = sql(`SELECT sus_zzzzsys_access_id FROM zzzzsys_user WHERE sus_login_name = '${anna}'`);
	const oldMail = sql(`SELECT IFNULL(HEX(sus_email), '-') FROM zzzzsys_user WHERE sus_login_name = '${anna}'`);
	const prov = require('child_process').spawn('python3', [path.join(__dirname, 'fakeoidc.py'), olog, String(port)], { stdio: 'ignore' });
	const person = async (j) => { const r = await fetch(iss + '/set', { method: 'POST', body: JSON.stringify(j) }); expect(r.ok, 'fake provider /set'); };
	const fresh = async () => {                          // a visitor in English
		const ctx = await browser.newContext(); const q = await ctx.newPage();
		await q.goto(BASE + 'index.php?p=lang&l=en-GB&r=p%3Dlogin');
		return q;
	};
	const ssoLogin = async () => {
		const q = await fresh();
		expect(await q.locator('#nuSsoBtn').count() === 1, 'no SSO button on the sign-in page');
		await Promise.all([q.waitForLoadState('networkidle'), q.click('#nuSsoBtn')]);
		await q.waitForLoadState('networkidle');
		return q;
	};
	const save = async () => { await Promise.all([p.waitForNavigation(), p.click('button[data-nu-save]')]); await p.waitForLoadState('networkidle'); };
	try {
		sql("DELETE FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id IN ('sso', 'sso_cache')");
		sql("DELETE FROM zzzzsys_nunext_log WHERE event IN ('login_failed', 'login_locked')");
		sql(`UPDATE zzzzsys_user SET sus_email = 'anna.sso@example.com' WHERE sus_login_name = '${anna}'`);
		await new Promise(r => setTimeout(r, 800));
		await open(p, 'index.php?p=sso');
		expect((await p.inputValue('#ssoRedirect')).endsWith('/oauth.php'), 'redirect URI');
		expect(await p.locator('#ssoTestBtn.disabled').count() === 1, 'Test sign-in enabled without a provider');
		// errors: on without issuer / client
		await p.check('#ssoOn');
		await save();
		expect(await p.locator('#ssoIssuer.is-invalid').count() === 1 && await p.locator('#ssoClientId.is-invalid').count() === 1, 'missing fields not marked');
		await p.selectOption('#ssoKind', 'other');
		await p.fill('#ssoIssuer', iss + '/'); await p.fill('#ssoClientId', 'cid'); await p.fill('#ssoSecret', 'csec');
		await p.uncheck('#ssoOn');                       // first test while still off
		await save();
		let st = JSON.parse(sql("SELECT setting_value FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'sso'"));
		expect(st.issuer === iss && st.client_id === 'cid' && st.on === false, 'stored: ' + JSON.stringify(st));
		expect(st.client_secret !== 'csec' && /^(enc|plain):/.test(st.client_secret), 'secret stored as is');
		// Test sign-in (off): result for anna, nothing changed, still the globeadmin
		await person({ email: 'Anna.SSO@example.com', name: 'Anna', groups: [] });
		await Promise.all([p.waitForURL(/p=sso/, { timeout: 15000 }), p.click('#ssoTestBtn')]);
		await p.waitForLoadState('networkidle');
		expect(await p.getAttribute('#ssoTestResult .alert', 'data-ok') === '1' && /sample_anna/.test(await p.textContent('#ssoTestResult')), 'test result: ' + await p.textContent('#ssoTestCard'));
		expect(/anna\.sso@example\.com/i.test(await p.textContent('#ssoTestClaims')), 'claims shown');
		const ol = fs.readFileSync(olog, 'utf8');
		expect(/authorize ok=True/.test(ol) && /token code=ok/.test(ol) && !/refused/.test(ol), 'PKCE / client: ' + ol.split('\n').join(' | '));
		// off: no button on the sign-in page
		let q = await fresh();
		expect(await q.locator('#nuSsoBtn').count() === 0, 'SSO button while off');
		await q.context().close();
		// on: anna signs in with SSO
		await open(p, 'index.php?p=sso'); await p.check('#ssoOn'); await save();
		q = await ssoLogin();
		expect(!/p=login/.test(q.url()) && await q.locator('#nuSsoBtn').count() === 0, 'anna not signed in: ' + q.url() + ' ' + (await q.textContent('body')).slice(0, 300));
		expect(+sql(`SELECT COUNT(*) FROM zzzzsys_nunext_log WHERE event = 'login' AND details LIKE '%sso%' AND user_id = (SELECT zzzzsys_user_id FROM zzzzsys_user WHERE sus_login_name = '${anna}')`) >= 1, 'login via sso not logged');
		await q.context().close();
		// refusals
		const refused = async (j, re, what) => {
			await person(j);
			const r = await ssoLogin();
			expect(/p=login/.test(r.url()) && re.test(await r.textContent('body')), what + ': ' + r.url() + ' ' + (await r.textContent('body')).replace(/\s+/g, ' ').slice(0, 300));
			await r.context().close();
		};
		await refused({ email: 'nobody@example.com', name: 'Nobody' }, /no user with this e-mail/, 'unknown user');
		await refused({ email: 'anna.sso@example.com', bad_sig: true }, /could not be verified \(signature\)/, 'bad signature');
		await refused({ email: 'anna.sso@example.com', email_verified: false }, /no verified e-mail/, 'unverified e-mail');
		await refused({ email: 'anna.sso@example.com', aud: 'other-client' }, /could not be verified \(audience\)/, 'audience');
		await refused({ email: 'anna.sso@example.com', nonce: 'x' }, /could not be verified \(nonce\)/, 'nonce');
		await refused({ email: 'anna.sso@example.com', deny: true }, /refused the sign-in: access_denied/, 'provider error');
		q = await fresh();
		await q.goto(BASE + 'oauth.php?code=x&state=sso.foreign'); await q.waitForLoadState('networkidle');
		expect(/p=login/.test(q.url()) && /too long or was started in another window/.test(await q.textContent('body')), 'foreign state');
		await q.context().close();
		expect(+sql("SELECT COUNT(*) FROM zzzzsys_nunext_log WHERE event = 'sso_refused'") >= 6, 'refusals not logged');
		// new users: by the group map (first match), with the domain check
		await open(p, 'index.php?p=sso');
		await p.check('#ssoCreate');
		expect(await p.locator('#ssoDefaultWrap').isVisible(), 'default level hidden');
		await p.fill('#ssoDomains', 'example.com');
		await p.locator('#ssoMap tr.ssoMapRow input').first().fill('Staff');
		await p.locator('#ssoMap tr.ssoMapRow select').first().selectOption(lvl);
		await save();
		st = JSON.parse(sql("SELECT setting_value FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'sso'"));
		expect(st.create && st.group_map.length === 1 && st.group_map[0].access === lvl && st.client_secret !== '', 'map / secret kept: ' + JSON.stringify(st));
		await refused({ email: 'new@other.org', groups: ['staff'] }, /this e-mail domain/, 'domain');
		await person({ email: 'new.sso@example.com', name: 'New Person', groups: ['other', 'staff'] });
		q = await ssoLogin();
		expect(!/p=login/.test(q.url()), 'new user not signed in: ' + (await q.textContent('body')).slice(0, 200));
		await q.context().close();
		expect(sql("SELECT CONCAT(sus_zzzzsys_access_id, '|', sus_name) FROM zzzzsys_user WHERE sus_email = 'new.sso@example.com'") === lvl + '|New Person', 'created user');
		// SSO only for anna's level: the password is refused, the globeadmin is not affected
		await open(p, 'index.php?p=sso');
		await p.locator(`#ssoOnlyCard input[value="${lvl}"]`).check();
		await save();
		q = await fresh();
		await q.fill('#username', anna); await q.fill('#password', UPW);
		await Promise.all([q.waitForLoadState('networkidle'), q.click('form button[type=submit]:not([name=demo_user])')]);
		expect(/p=login/.test(q.url()) && /sign in with single sign-on/i.test(await q.textContent('body')), 'password not refused: ' + q.url());
		await q.context().close();
		await open(p, 'index.php?p=sso');
		expect(/p=sso/.test(p.url()), 'globeadmin lost the page');
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		prov.kill();
		sql("DELETE FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id IN ('sso', 'sso_cache')");
		sql("DELETE FROM zzzzsys_user WHERE sus_email = 'new.sso@example.com'");
		sql(`UPDATE zzzzsys_user SET sus_email = ${oldMail === '-' ? 'NULL' : "UNHEX('" + oldMail + "')"} WHERE sus_login_name = '${anna}'`);
		sql("DELETE FROM zzzzsys_nunext_log WHERE event IN ('login_failed', 'login_locked', 'sso_refused', 'sso_test', 'sso_user_created', 'sso_access_changed')");
		fs.rmSync(olog, { force: true });
	}
};

T.ip_access = async (s) => {                            // 0.8.722: IP access – default list, exception per level, globeadmin rule, lock-out guard, session check, test, cron off
	const p = s.ga, anna = 'sample_anna';
	const lvl = sql(`SELECT sus_zzzzsys_access_id FROM zzzzsys_user WHERE sus_login_name = '${anna}'`);
	const set = (j) => sql(`REPLACE INTO zzzzsys_nunext_setting (zzzzsys_nunext_setting_id, setting_value) VALUES ('ip_access', '${JSON.stringify(j)}')`);
	const tryLogin = async () => {
		const ctx = await browser.newContext(); const q = await ctx.newPage();
		await q.goto(BASE + 'index.php?p=login'); await q.fill('#username', anna); await q.fill('#password', UPW);
		await Promise.all([q.waitForLoadState('networkidle'), q.click('form button[type=submit]:not([name=demo_user])')]);
		return q;
	};
	try {
		sql("DELETE FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'ip_access'");
		sql("DELETE FROM zzzzsys_nunext_log WHERE event IN ('login_failed', 'ip_refused')");
		await open(p, 'index.php?p=ipaccess');
		expect(await p.textContent('#ipaMine') === '127.0.0.1', 'own address: ' + await p.textContent('#ipaMine'));
		// lock-out guard: globeadmin "same as all access levels" with a list without 127.0.0.1
		await p.check('#ipaOn'); await p.fill('#ipaDefault', '10.99.0.0/16  # office\n203.0.113.7');
		await Promise.all([p.waitForNavigation(), p.click('button[data-nu-save]')]); await p.waitForLoadState('networkidle');
		expect(await p.locator('#ipaSelfErr').count() === 1, 'lock-out not refused');
		expect(sql("SELECT COUNT(*) FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'ip_access'") === '0', 'saved although locked out');
		// invalid entry
		await p.fill('#ipaDefault', '10.99.0.0/16\nnot-an-ip');
		await Promise.all([p.waitForNavigation(), p.click('button[data-nu-save]')]); await p.waitForLoadState('networkidle');
		expect(await p.locator('#ipaDefault.is-invalid').count() === 1 && /not-an-ip/.test(await p.textContent('#ipaDefaultCard')), 'invalid rule not marked');
		// own ranges field only for "Own ranges"; globeadmin any address → saved
		expect(await p.locator('#ipaGaRangesWrap').isHidden(), 'ga ranges shown for default');
		await p.selectOption('#ipaGaMode', 'ranges');
		expect(await p.locator('#ipaGaRangesWrap').isVisible(), 'ga ranges not shown');
		await p.selectOption('#ipaGaMode', 'any');
		await p.fill('#ipaDefault', '10.99.0.0/16  # office\n203.0.113.7');
		await Promise.all([p.waitForNavigation(), p.click('button[data-nu-save]')]); await p.waitForLoadState('networkidle');
		const st = JSON.parse(sql("SELECT setting_value FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'ip_access'"));
		expect(st.on === true && st.default.join(',') === '10.99.0.0/16,203.0.113.7' && st.ga.mode === 'any', 'stored: ' + JSON.stringify(st));
		// a user of a level without an exception is refused at sign-in (and logged)
		let q = await tryLogin();
		expect(/p=login/.test(q.url()) && /not allowed from this network/.test(await q.textContent('body')), 'user not refused: ' + q.url());
		await q.context().close();
		expect(+sql("SELECT COUNT(*) FROM zzzzsys_nunext_log WHERE event = 'ip_refused'") >= 1, 'no ip_refused log row');
		// exception for the user's level: own ranges with 127.0.0.0/8 → signs in
		await open(p, 'index.php?p=ipaccess');
		const sel = p.locator(`tr[data-ipa-level="${lvl}"] select.ipaMode`);
		await sel.selectOption('ranges');
		await p.locator(`tr[data-ipa-level="${lvl}"] textarea`).fill('127.0.0.0/8');
		expect(await p.textContent('#ipaExcCount') === '1', 'exception count');
		await Promise.all([p.waitForNavigation(), p.click('button[data-nu-save]')]); await p.waitForLoadState('networkidle');
		expect(JSON.parse(sql("SELECT setting_value FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'ip_access'")).levels[lvl].ranges[0] === '127.0.0.0/8', 'level exception not stored');
		sql("DELETE FROM zzzzsys_nunext_log WHERE event IN ('login_failed')");
		q = await tryLogin();
		expect(!/p=login/.test(q.url()), 'user with exception refused: ' + q.url());
		// the running session ends when its address is no longer allowed
		set({ on: true, default: ['10.99.0.0/16'], levels: {}, ga: { mode: 'any', ranges: [] } });
		await open(q, 'index.php?p=home');
		expect(/p=login/.test(q.url()) && /not allowed from this network/.test(await q.textContent('body')), 'session not ended: ' + q.url());
		await q.context().close();
		// test an address (saved rules)
		await open(p, 'index.php?p=ipaccess&test=10.99.3.4');
		expect(await p.getAttribute('#ipaTestGa', 'data-ok') === '1' && (await p.textContent('#ipaTestAllowed')).length > 0, 'test 10.99.3.4');
		await open(p, 'index.php?p=ipaccess&test=8.8.8.8');
		expect(await p.textContent('#ipaTestAllowed') === '' && /sample/.test(await p.textContent('#ipaTestRefused')), 'test 8.8.8.8');
		// security check line and the shell switch
		await open(p, 'index.php?p=securitycheck');
		expect(/IP access/.test(await p.textContent('#secChecks')), 'security check line');
		if (SITE) {
			execSync('php nucron.php iprules off', { cwd: SITE });
			expect(JSON.parse(sql("SELECT setting_value FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'ip_access'")).on === false, 'cron off');
		}
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		sql("DELETE FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'ip_access'");
		sql("DELETE FROM zzzzsys_nunext_log WHERE event IN ('login_failed', 'ip_refused', 'ip_access_off')");
	}
};

// 0.8.804: page numbers – "P100" + Enter in the start page search and in Ctrl+K opens the page; a tab suffix; an unknown number comes back
T.page_numbers = async (s) => {
	const p = s.ga;
	await open(p, 'index.php?p=home');
	await p.fill('#nuHomeSearch', 'P110');
	await Promise.all([p.waitForNavigation({ waitUntil: 'load' }), p.press('#nuHomeSearch', 'Enter')]);
	expect(/p=access\b/.test(p.url()), 'start page search: P110 did not open the access levels: ' + p.url());
	await open(p, 'index.php?p=users');
	await p.keyboard.press('Control+k'); await p.waitForSelector('#nuPaletteInput', { state: 'visible' });
	await p.fill('#nuPaletteInput', 'p 700.2');
	await Promise.all([p.waitForNavigation({ waitUntil: 'load' }), p.press('#nuPaletteInput', 'Enter')]);
	expect(/p=update/.test(p.url()) && /tab=backups/.test(p.url()), 'Ctrl+K: P700.2 did not open Update → Backups: ' + p.url());
	await open(p, 'index.php?p=users');
	await p.keyboard.press('Control+k'); await p.waitForSelector('#nuPaletteInput', { state: 'visible' });
	await p.fill('#nuPaletteInput', 'P999');
	await Promise.all([p.waitForNavigation({ waitUntil: 'load' }), p.press('#nuPaletteInput', 'Enter')]);
	expect(/p=users/.test(p.url()) && /P999/.test(await p.textContent('body')), 'unknown number: not back with a message: ' + p.url());
	await open(p, 'index.php?p=home');
	await p.fill('#nuHomeSearch', 'P001'); await p.press('#nuHomeSearch', 'Enter'); await p.waitForLoadState('load');
	expect(/p=home/.test(p.url()), 'P001: ' + p.url());
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
};

T.home_search_list = async (s) => {                     // 0.8.723: start page search = one list (tiles first, then pages / forms / procedures …), kinds filter
	const p = s.ga;
	await open(p, 'index.php?p=home'); await p.evaluate(() => { try { localStorage.removeItem('nunext-home-search-kinds'); } catch (e) { /* */ } });
	await open(p, 'index.php?p=home');
	await p.fill('#nuHomeSearch', 'update'); await p.waitForTimeout(800);
	const keys = await p.$$eval('#nuHomeSearchMore [data-nu-res]', (a) => a.map((x) => x.getAttribute('data-nu-res')));
	expect(keys[0] === 't:update' && await p.locator('#nuHomeView').isHidden() && !(await p.locator('#nuHomeSearchMore h2').count()), 'tile not first / view shown: ' + keys.join(','));
	// customers: the sample form (f:) comes after the tiles; without forms it is gone
	await p.fill('#nuHomeSearch', 'customer'); await p.waitForTimeout(500);
	let k2 = await p.$$eval('#nuHomeSearchMore [data-nu-res]', (a) => a.map((x) => x.getAttribute('data-nu-res')));
	const lastTile = k2.map((k) => k.startsWith('t:')).lastIndexOf(true), firstForm = k2.findIndex((k) => k.startsWith('f:'));
	expect(firstForm >= 0 && (lastTile < 0 || lastTile < firstForm || k2.slice(0, firstForm).every((k) => k.startsWith('t:'))), 'order: ' + k2.join(','));
	await p.click('#nuHomeSearchKinds'); await p.waitForTimeout(200);
	await p.uncheck('#nuHomeSk_forms'); await p.waitForTimeout(200);
	k2 = await p.$$eval('#nuHomeSearchMore [data-nu-res]', (a) => a.map((x) => x.getAttribute('data-nu-res')));
	expect(!k2.some((k) => k.startsWith('f:')) && await p.locator('#nuHomeSearchKinds.nuHomeSkOn').count() === 1, 'forms still listed: ' + k2.join(','));
	await open(p, 'index.php?p=home');
	expect(!(await p.isChecked('#nuHomeSk_forms')), 'kinds not kept');
	await p.click('#nuHomeSearchKinds'); await p.click('#nuHomeSkAll'); await p.waitForTimeout(150);
	expect(await p.isChecked('#nuHomeSk_forms') && await p.locator('#nuHomeSearchKinds.nuHomeSkOn').count() === 0, 'include everything');
	await p.keyboard.press('Escape');
	// ↓ / ↑ move the selection (first one selected), Enter opens the selected one (0.8.724)
	await p.fill('#nuHomeSearch', 'update');  await p.waitForTimeout(400);
	const sel = () => p.$eval('#nuHomeSearchMore [data-nu-res].active', (a) => a.getAttribute('data-nu-res'));
	expect(await sel() === 't:update', 'first result not selected');
	await p.press('#nuHomeSearch', 'ArrowDown'); const second = await sel();
	await p.press('#nuHomeSearch', 'ArrowUp'); expect(await sel() === 't:update' && second !== 't:update', 'arrows: ' + second);
	await p.press('#nuHomeSearch', 'ArrowUp'); expect(await sel() === 't:update', 'up past the first');
	await Promise.all([p.waitForURL(/p=update/), p.press('#nuHomeSearch', 'Enter')]);
	await open(p, 'index.php?p=home');
	await p.fill('#nuHomeSearch', 'update');  await p.waitForTimeout(400);
	await p.press('#nuHomeSearch', 'ArrowDown');
	const target = await p.$eval('#nuHomeSearchMore [data-nu-res].active', (a) => a.getAttribute('href'));
	await Promise.all([p.waitForURL((u) => u.href.includes(target.replace(/^.*\?/, ''))), p.press('#nuHomeSearch', 'Enter')]);
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
};

T.home_search_ctx = async (s) => {                     // 0.8.855: right-click / long press on a tile result of the start page search = the tile's menu
	const p = s.ga;
	await open(p, 'index.php?p=home');
	const wasFav = await p.$eval('[data-nu-tile="update"]', (a) => a.getAttribute('data-nu-fav') === '1');
	await p.fill('#nuHomeSearch', 'update'); await p.waitForTimeout(600);
	await p.click('#nuHomeSearchMore [data-nu-res="t:update"]', { button: 'right' });
	await p.waitForTimeout(200);
	expect(await p.locator('.nuHomeCtx').count() === 1, 'no menu on a tile result');
	const items = await p.$$eval('.nuHomeCtx .dropdown-item', (a) => a.map((x) => x.textContent.trim()));
	expect(items.length >= 1, 'menu without entries');
	await Promise.all([p.waitForNavigation(), p.click('.nuHomeCtx .dropdown-item >> nth=0')]);
	await p.waitForTimeout(800);
	expect(await p.inputValue('#nuHomeSearch') === 'update' && await p.locator('#nuHomeSearchMore [data-nu-res="t:update"]').count() === 1, 'search not kept after the reload');
	const isFav = await p.$eval('[data-nu-tile="update"]', (a) => a.getAttribute('data-nu-fav') === '1');
	expect(isFav !== wasFav, 'favourite not toggled');
	// back as it was
	await p.click('#nuHomeSearchMore [data-nu-res="t:update"]', { button: 'right' }); await p.waitForTimeout(200);
	await Promise.all([p.waitForNavigation(), p.click('.nuHomeCtx .dropdown-item >> nth=0')]);
	await p.waitForTimeout(500);
	expect(await p.$eval('[data-nu-tile="update"]', (a) => a.getAttribute('data-nu-fav') === '1') === wasFav, 'favourite not back');
	// a result that is no tile: no own menu
	await p.fill('#nuHomeSearch', 'customer'); await p.waitForTimeout(600);
	const f = p.locator('#nuHomeSearchMore [data-nu-res^="f:"]').first();
	if (await f.count()) {
		await f.click({ button: 'right' }); await p.waitForTimeout(200);
		expect(await p.locator('.nuHomeCtx').count() === 0, 'menu on a form result');
		await p.keyboard.press('Escape');
	}
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
};

T.users_filter_width = async (s) => {                   // 0.8.729: users list filters on desktop – 250 px each, the same gap between them
	const p = s.ga;
	await p.setViewportSize({ width: 1400, height: 900 });
	await open(p, 'index.php?p=users');
	await p.waitForTimeout(400);
	expect(!(await p.isVisible('#nuLvFilters')), 'users list: filters shown by default on desktop (0.8.751)');
	await open(p, 'index.php?p=users&access=' + encodeURIComponent(sql("SELECT zzzzsys_access_id FROM zzzzsys_access LIMIT 1").trim()));
	await p.waitForTimeout(400);
	expect(await p.isVisible('#nuLvFilters'), 'users list: filters folded while one is set');
	await open(p, 'index.php?p=users');
	if (!(await p.isVisible('#nuLvFilters'))) { await p.click('[aria-controls="nuLvFilters"]'); await p.waitForTimeout(500); }
	const box = await p.$$eval('#nuLvFilters .row > div', (d) => d.map((x) => { const r = x.getBoundingClientRect(); return [r.left, r.top, r.width]; }));
	const row = box.filter((b) => Math.abs(b[1] - box[0][1]) < 2), gaps = row.slice(1).map((b, i) => Math.round(b[0] - row[i][0] - row[i][2]));
	expect(box.length >= 4 && box.every((b) => Math.round(b[2]) === 250) && new Set(gaps).size === 1, 'widths / gaps: ' + JSON.stringify(box) + ' ' + gaps.join(','));
	// 0.8.732: a chosen value keeps the searchable select one line high (the search input wrapped below it)
	const lvl = sql("SELECT zzzzsys_access_id FROM zzzzsys_access ORDER BY sal_code LIMIT 1");
	await open(p, 'index.php?p=users&access=' + encodeURIComponent(lvl));
	const hs = await p.evaluate(() => [document.querySelector('#lvf_access + .ts-wrapper').getBoundingClientRect().height, document.getElementById('lvf_pos').getBoundingClientRect().height]);
	expect(Math.abs(hs[0] - hs[1]) < 2, 'access level filter height with a value: ' + hs.join(' / '));
	await p.click('#lvf_access + .ts-wrapper .ts-control'); await p.keyboard.type(lvl.slice(0, 4)); await p.waitForTimeout(300);
	expect(await p.locator('#lvf_access + .ts-wrapper .ts-dropdown .option').count() > 0, 'typing in the searchable select');
	await p.keyboard.press('Escape');
	await p.setViewportSize({ width: 1300, height: 900 });
};

T.review_765 = async (s) => {                          // 0.8.765: design mode (redo, form messages, column picker), existing-database warning, lazy code tools
	const p = s.ga, F = 'samplecustomer';
	const keep = path.join(os.tmpdir(), 'nunext-e2e-765.sql');
	execSync('mysqldump ' + DB + ' zzzzsys_browse zzzzsys_form zzzzsys_object zzzzsys_nunext_form_history zzzzsys_nunext_form_draft > ' + keep);
	const before = sql("SELECT setting_value FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'db_origin'");
	try {
		// the form page loads the code tools only in design mode (they come with CodeMirror otherwise)
		await open(p, 'index.php?p=form&f=' + F + '&r=sample_cus_01');
		expect(await p.locator('script[src*="nucodetools.js"]').count() === 0, 'code tools loaded on a plain form page');
		sql(`DELETE FROM zzzzsys_nunext_form_draft WHERE form_id = '${F}'`);
		await open(p, 'index.php?p=form&f=' + F + '&r=sample_cus_01&design=1'); await p.waitForSelector('#nuDsBar'); await p.waitForTimeout(800);
		expect(await p.locator('script[src*="nucodetools.js"]').count() === 1, 'code tools missing in design mode');
		// messages of the form's own code: collected in the bar, no toast over the panel
		const n0 = await p.evaluate(() => (window.nuNext.formMsgs || []).length);
		await p.evaluate(() => { window.nuToast('E2E form toast'); window.nuMessage(['E2E form message']); });
		await p.waitForTimeout(300);
		expect(await p.isVisible('#nuDsFormMsgs') && (await p.textContent('#nuDsFormMsgs')).trim() === String(n0 + 2) && await p.locator('#nuToasts .toast').count() === 0 && !(await p.locator('text=E2E form message').isVisible().catch(() => false)), 'form messages not collected: ' + n0 + ' / ' + (await p.textContent('#nuDsFormMsgs')) + ' / ' + await p.isVisible('#nuDsFormMsgs') + ' / ' + await p.locator('#nuToasts .toast').count() + ' / ' + await p.locator('#nuMessageDiv').count() + ' ' + (await p.locator('#nuMessageDiv').textContent().catch(() => '')));
		// redo: change a label, undo, redo
		const lbl = sql("SELECT sob_all_label FROM zzzzsys_object WHERE zzzzsys_object_id = 'sample_customer_o2'");
		await p.click('#nuw_cus_name .nuDesignOverlay'); await p.waitForTimeout(500);
		await p.fill('#nuDsPanel [data-key="sob_all_label"]', 'E2E redo'); await p.press('#nuDsPanel [data-key="sob_all_label"]', 'Enter'); await p.waitForTimeout(1500);
		const snapLabel = () => sql(`SELECT jt.l FROM zzzzsys_nunext_form_draft d, JSON_TABLE(d.snapshot, '$.objects[*]' COLUMNS(id VARCHAR(60) PATH '$.zzzzsys_object_id', l VARCHAR(200) PATH '$.sob_all_label')) jt WHERE d.form_id = '${F}' AND d.status = 'open' AND jt.id = 'sample_customer_o2'`);
		expect(snapLabel() === 'E2E redo', 'label not in the draft: ' + snapLabel());
		await p.click('#nuDsUndo'); await p.waitForSelector('#nuDsBar'); await p.waitForTimeout(1500);
		expect(snapLabel() === lbl, 'undo: ' + snapLabel());
		expect(await p.isEnabled('#nuDsRedo'), 'redo not offered after undo');
		await p.keyboard.press('Control+y'); await p.waitForTimeout(1800);
		expect(snapLabel() === 'E2E redo', 'redo (Ctrl+Y): ' + snapLabel());
		// list design: "+" asks for the column first – no draft change before a choice
		sql(`DELETE FROM zzzzsys_nunext_form_draft WHERE form_id = '${F}'`);
		await open(p, 'index.php?p=form&f=' + F + '&design=1'); await p.waitForSelector('#nuDsBar'); await p.waitForTimeout(800);
		await p.click('#nuDsColAddTh'); await p.waitForSelector('#nuDsColPick'); await p.waitForTimeout(700);
		expect(await p.locator('#nuDsColPick [data-col-name]').count() > 0 && sql(`SELECT COUNT(*) FROM zzzzsys_nunext_form_draft WHERE form_id = '${F}' AND status = 'open'`) === '0', 'column picker');
		await p.keyboard.press('Escape'); await p.waitForTimeout(200);
		expect(await p.locator('#nuDsColPick').count() === 0, 'Esc closes the picker');
		// compression rules for the static files
		expect(['assets/.htaccess', 'vendor/bundled/.htaccess'].every((f) => /mod_deflate[\s\S]*DEFLATE text\/css application\/javascript/.test(fs.readFileSync(path.join(__dirname, '..', '..', f), 'utf8'))), 'compression rules missing');
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		execSync('mysql ' + DB + ' < ' + keep);
		sql("DELETE FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id IN ('db_origin', 'existing_db_warn_hidden')" + (before !== '' ? "; INSERT INTO zzzzsys_nunext_setting (zzzzsys_nunext_setting_id, setting_value) VALUES ('db_origin', '" + before + "')" : ''));
	}
};

T.proc_fields_layout = async (s) => {                 // 0.8.837: procedure details in two rows, fields sized to their content; Start from hint as (i)
	await open(s.ga, 'index.php?p=procedures&id=sample_proc_xlsx');
	await s.ga.evaluate(() => { document.getElementById('procFields').open = true; }); await s.ga.waitForTimeout(200);
	const g = await s.ga.evaluate(() => { const w = (sel) => { const e = document.querySelector('#procTabPhp ' + sel); return e ? Math.round(e.getBoundingClientRect().width) : -1; };
		const top = (sel) => Math.round(document.querySelector('#procTabPhp ' + sel).getBoundingClientRect().top);
		return { code: w('.pf_code'), desc: w('.pf_description'), status: w('.pf_status'), launch: w('.pf_zzzzsys_form_id'), row1: top('.pf_code') === top('.pf_status'), row2: top('.pf_group') === top('.pf_zzzzsys_form_id'),
			tip: !!document.querySelector('#procTabPhp .pf_zzzzsys_form_id .nuInfoTip'), hint: !!document.querySelector('#procTabPhp .procHint') }; });
	expect(g.code <= 360 && g.desc <= 560 && g.status <= 200 && g.launch <= 360 && g.row1 && g.row2 && g.tip && !g.hint, 'procedure fields: ' + JSON.stringify(g));
};

T.nav_crumbs_noflash = async (s) => {                 // 0.8.836: with the compact bar the page's breadcrumb never shows below it (hidden by CSS before nuapp.js runs)
	const had = sql("SELECT COUNT(*) FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'branding'") !== '0';
	if (had) { s.skip = 'branding set'; return; }
	sql(`INSERT INTO zzzzsys_nunext_setting (zzzzsys_nunext_setting_id, setting_value) VALUES ('branding', '{"logo_show":"login"}')`);
	const ctx = await browser.newContext({ viewport: { width: 1300, height: 800 }, javaScriptEnabled: false, storageState: await s.ga.context().storageState() });
	const p = await ctx.newPage();
	try {
		for (const u of ['index.php?p=form&f=samplecustomer', 'index.php?p=form&f=samplecustomer&r=sample_cus_01']) {
			await p.goto(BASE + u);
			const r = await p.evaluate(() => { const n = document.querySelector('#main nav[aria-label="breadcrumb"]'); return { slot: !!document.getElementById('nuNavCrumbs'), has: !!n, shown: n ? getComputedStyle(n).display !== 'none' : false }; });
			expect(r.slot && r.has && !r.shown, u + ': breadcrumb shown in the page before the script: ' + JSON.stringify(r));
		}
		await p.setViewportSize({ width: 390, height: 800 });
		await p.goto(BASE + 'index.php?p=form&f=samplecustomer&r=sample_cus_01');
		// phones (0.8.1003, mockup B): the breadcrumb is replaced by the back link "‹ <list>" above the title
		expect(await p.evaluate(() => { const b = document.querySelector('.nuPhBack'); return !!b && getComputedStyle(b).display !== 'none'; }), 'phone: no back link instead of the breadcrumb');
	} finally { await ctx.close(); sql("DELETE FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'branding'"); }
};

T.record_compact = async (s) => {                     // 0.8.835: record pages compact (card padding, labels, fields); 16 px fields on phones
	const id = sql("SELECT zzzzsys_user_id FROM zzzzsys_user WHERE sus_login_name LIKE 'sample_%' LIMIT 1").trim();
	await open(s.ga, 'index.php?p=user&id=' + encodeURIComponent(id));
	const m = await s.ga.evaluate(() => { const b = document.querySelector('main .card > .card-body'), i = document.getElementById('sus_name'), l = document.querySelector('main .form-label');
		return { pad: parseFloat(getComputedStyle(b).paddingTop), fs: parseFloat(getComputedStyle(i).fontSize), h: i.getBoundingClientRect().height, lab: parseFloat(getComputedStyle(l).fontSize) }; });
	expect(m.pad <= 12.5 && m.fs < 15 && m.h <= 33 && m.lab <= 14.5, 'record page not compact: ' + JSON.stringify(m));
	const ctx = await browser.newContext({ locale: 'en-GB', viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, storageState: await s.ga.context().storageState() });
	const p = await ctx.newPage();
	try {
		await p.goto(BASE + 'index.php?p=user&id=' + encodeURIComponent(id));
		const fs = await p.evaluate(() => parseFloat(getComputedStyle(document.getElementById('sus_name')).fontSize));
		expect(fs >= 16, 'phone: field text below 16 px (iOS zooms): ' + fs);
	} finally { await ctx.close(); }
	// a list page is not touched by it
	await open(s.ga, 'index.php?p=users');
	expect(!(await s.ga.evaluate(() => document.body.matches(':has(.nuRecHead)'))), 'users list counted as a record page');
};

