// 0.8.518: input buttons and run buttons of forms look the same (class nuFormBtn); an input button keeps the object's height
// 0.8.621: solid in the accent colour with white text; no icons of our own on run buttons (new tab = tooltip); text colour on a background
// of the form's CSS (white, dark on light ones; a colour of the form's CSS stays); one line, cut-off label as tooltip; HTML object headings
T.form_buttons = async (s) => {
	const p = s.ga;
	const oldTarget = sql("SELECT sob_run_target FROM zzzzsys_object WHERE sob_all_zzzzsys_form_id = 'sampleall' AND sob_all_id = 'all_run_form'");
	try {
		sql("UPDATE zzzzsys_object SET sob_run_target = '2' WHERE sob_all_zzzzsys_form_id = 'sampleall' AND sob_all_id = 'all_run_form'");
		await open(p, 'index.php?p=form&f=sampleall&r=sample_all_1');
		await p.locator('.nuTab', { hasText: 'Miscellaneous' }).click(); await p.waitForTimeout(300);
		const st = id => p.evaluate(i => { const e = document.getElementById(i), c = getComputedStyle(e), r = e.getBoundingClientRect();
			return { cls: e.classList.contains('nuFormBtn'), bg: c.backgroundColor, border: c.borderTopColor, radius: c.borderTopLeftRadius, color: c.color, h: Math.round(r.height),
				ws: c.whiteSpace, accent: getComputedStyle(document.documentElement).getPropertyValue('--nu-accent').trim(), ink: e.className }; }, id);
		const a = await st('all_spin_wait'), b = await st('all_spin_run');
		expect(a.cls && b.cls, 'class nuFormBtn missing: ' + JSON.stringify([a, b]));
		expect(a.bg === b.bg && a.border === b.border && a.radius === b.radius && a.color === b.color, 'input and run buttons differ: ' + JSON.stringify([a, b]));
		expect(a.h === 30 && b.h === 30, 'heights (object 30 px): ' + JSON.stringify([a.h, b.h]));
		const hex = a.accent.replace('#', ''), acc = 'rgb(' + [0, 2, 4].map(i => parseInt(hex.substr(i, 2), 16)).join(', ') + ')';
		expect(a.bg === acc && a.color === 'rgb(255, 255, 255)' && a.ws === 'nowrap', 'not solid accent / white / one line: ' + JSON.stringify(a) + ' ' + acc);
		// a background of the form's CSS: light → dark text, dark → white; a text colour of the form's CSS stays
		const ink = await p.evaluate(() => {
			const st = document.createElement('style');
			st.textContent = '#all_spin_wait { background-color: #ffd54a; } #all_spin_auto { background-color: #4cae4c; } #all_spin_run { background-color: #2e7d32; color: rgb(255, 255, 0); }';
			document.head.appendChild(st);
			window.nuNext.fitButtons(document);
			const c = id => { const e = document.getElementById(id); return [e.classList.contains('nuBtnInkDark') ? 'dark' : e.classList.contains('nuBtnInkLight') ? 'light' : '', getComputedStyle(e).color]; };
			const r = { wait: c('all_spin_wait'), auto: c('all_spin_auto'), run: c('all_spin_run') };
			st.remove(); window.nuNext.fitButtons(document);
			r.after = c('all_spin_wait');
			return r;
		});
		expect(ink.wait[0] === 'dark' && ink.wait[1] === 'rgb(30, 41, 59)', 'light background: no dark text ' + JSON.stringify(ink));
		expect(ink.auto[0] === 'light' && ink.auto[1] === 'rgb(255, 255, 255)', 'green background: no white text ' + JSON.stringify(ink));
		expect(ink.run[0] === '' && ink.run[1] === 'rgb(255, 255, 0)', 'own text colour replaced ' + JSON.stringify(ink));
		expect(ink.after[0] === '' && ink.after[1] === 'rgb(255, 255, 255)', 'class kept after the colour went ' + JSON.stringify(ink));
		// a label too long for its button: … and the full label as tooltip; wide again: no tooltip
		const cut = await p.evaluate(async () => {
			const e = document.getElementById('all_spin_wait'), w = e.parentNode.style.width;
			e.parentNode.style.width = '70px'; await new Promise(r => setTimeout(r, 250));
			const t1 = e.getAttribute('title'), ov = getComputedStyle(e).textOverflow;
			e.parentNode.style.width = w; await new Promise(r => setTimeout(r, 250));
			return { t1, ov, t2: e.getAttribute('title'), label: e.querySelector('.nuButtonLabel').textContent.trim() };
		});
		expect(cut.t1 === cut.label && cut.ov === 'ellipsis' && cut.t2 === null, 'cut-off label: ' + JSON.stringify(cut));
		// HTML objects: a heading is bold in the browser's size (13 px text in the pixel layout, as nuBuilder Forte), the sample's fs-6 heading keeps 16 px
		const hd = await p.evaluate(() => {
			const box = document.querySelector('#nuw_all_new_h_spin .nuHtml'), h = document.createElement('h3');
			h.textContent = 'e2e'; box.appendChild(h);
			const c = getComputedStyle(h), r = { w: c.fontWeight, fs: c.fontSize, six: getComputedStyle(box.querySelector('h6')).fontSize };
			h.remove(); return r;
		});
		expect(+hd.w >= 700 && Math.abs(parseFloat(hd.fs) - 15.21) < 0.2 && hd.six === '16px', 'HTML object headings: ' + JSON.stringify(hd));
		// run buttons: no icon of our own; a new tab is said in the tooltip
		await p.locator('.nuTab', { hasText: /^\s*Run\s*$/ }).click(); await p.waitForTimeout(300);
		const run = await p.evaluate(() => ['all_run_form', 'all_run_proc', 'all_run_report'].map(id => { const e = document.getElementById(id);
			return { id, icons: e.querySelectorAll('i.bi').length, hint: e.getAttribute('data-nu-run-hint') || '', title: e.getAttribute('title') || '' }; }));
		expect(run.every(r => r.icons === 0), 'icons on run buttons: ' + JSON.stringify(run));
		expect(run[0].hint !== '' && run[0].title === run[0].hint && run[1].hint === '' && run[1].title === '', 'new-tab hint: ' + JSON.stringify(run));
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		sql("UPDATE zzzzsys_object SET sob_run_target = " + (oldTarget === 'NULL' || oldTarget === '' ? "'0'" : "'" + oldTarget + "'") + " WHERE sob_all_zzzzsys_form_id = 'sampleall' AND sob_all_id = 'all_run_form'");
	}
};

// 0.8.520: a record opened anew starts on the first tab; the last tab is kept only for the same record (reload, Save)
T.form_first_tab = async (s) => {
	const p = s.ga;
	const active = () => p.evaluate(() => { const a = document.querySelector('.nuTab.active'); return a ? a.getAttribute('data-nu-tab') : null; });
	await open(p, 'index.php?p=form&f=sampleall');
	await Promise.all([p.waitForNavigation(), p.locator('#nuBrowseTable tbody tr.nuBrowseRow').first().click()]);
	await p.locator('.nuTab', { hasText: 'Charts' }).click(); await p.waitForTimeout(300);
	const tab = await active();
	expect(tab !== '0', 'tab not switched');
	await p.reload(); await p.waitForLoadState('load'); await p.waitForTimeout(300);
	expect(await active() === tab, 'reload: tab not kept');
	await p.goBack(); await p.waitForLoadState('load');
	await open(p, 'index.php?p=form&f=sampleall');
	await Promise.all([p.waitForNavigation(), p.locator('#nuBrowseTable tbody tr.nuBrowseRow').first().click()]);
	await p.waitForTimeout(300);
	expect(await active() === '0', 'opened again from the list: not on the first tab (' + await active() + ')');
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
};

// 0.8.606 / design mode 0.8.670: several objects as in nuBuilder Forte's arrange mode – Ctrl + click, box selection, Ctrl + A, group
// moves with the arrow keys, Shift + arrows = width, Arrange (align, space evenly, same size, order up / down), tab order numbers follow
// Up / Down, a text area follows its handle at once. The form is set to "never published", so every step is written to its rows directly.
T.design_arrange = async (s) => {
	const p = s.ga, F = 'samplecustomer';
	const LEFT = { position: { x: 6, y: 6 } };
	const meta = ['zzzzsys_object', 'zzzzsys_form', 'zzzzsys_nunext_form_history', 'zzzzsys_nunext_form_draft'];
	const keep = path.join(require('os').tmpdir(), 'nunext-e2e-arrange.sql');
	execSync('mysqldump ' + DB + ' ' + meta.join(' ') + ' > ' + keep);
	const q = (id, col) => sql(`SELECT ${col} FROM zzzzsys_object WHERE sob_all_zzzzsys_form_id = '${F}' AND sob_all_id = '${id}'`);
	const act = async (a) => { await p.click('#nuDsPanel [data-ds-arrange="' + a + '"]'); await p.waitForTimeout(1200); };
	const nsel = () => p.locator('.nuBuilderSelected, .nuDesignSelected').count();
	try {
		sql(`UPDATE zzzzsys_object SET sob_all_left = 200 WHERE sob_all_zzzzsys_form_id = '${F}' AND sob_all_id = 'cus_name'; UPDATE zzzzsys_form SET sfo_status = '0' WHERE zzzzsys_form_id = '${F}'; DELETE FROM zzzzsys_nunext_form_draft WHERE form_id = '${F}'`);
		await open(p, 'index.php?p=form&f=' + F + '&r=-1&design=1'); await p.waitForSelector('#nuDsRail'); await p.waitForTimeout(700);
		await p.click('#nuw_cus_code .nuDesignOverlay', LEFT);
		await p.click('#nuw_cus_name .nuDesignOverlay', { ...LEFT, modifiers: ['Control'] }); await p.waitForTimeout(300);
		expect(await nsel() === 2 && await p.locator('#nuDsArrange').count() === 1, 'two objects not selected');
		expect(await p.isDisabled('#nuDsPanel [data-ds-arrange="vertical"]'), 'Vertical with two objects');
		await act('left');
		expect(q('cus_name', 'sob_all_left') === '170' && q('cus_code', 'sob_all_left') === '170', 'Left: ' + q('cus_name', 'sob_all_left'));
		await act('widest');
		expect(q('cus_code', 'sob_all_width') === q('cus_name', 'sob_all_width'), 'Widest: ' + q('cus_code', 'sob_all_width') + ' / ' + q('cus_name', 'sob_all_width'));
		// keys: the group moves; Shift = width
		const top0 = +q('cus_code', 'sob_all_top'), top1 = +q('cus_name', 'sob_all_top'), w0 = +q('cus_name', 'sob_all_width');
		await p.locator('body').press('ArrowDown'); await p.waitForTimeout(1200);
		expect(+q('cus_code', 'sob_all_top') === top0 + 5 && +q('cus_name', 'sob_all_top') === top1 + 5, 'arrow: ' + q('cus_code', 'sob_all_top') + ' / ' + q('cus_name', 'sob_all_top'));
		await p.locator('body').press('Shift+ArrowRight'); await p.waitForTimeout(1200);
		expect(+q('cus_name', 'sob_all_width') === w0 + 5, 'Shift+arrow width: ' + q('cus_name', 'sob_all_width'));
		// order: cus_name up before cus_code; the tab order numbers follow without a reload
		await p.locator('body').press('Escape'); await p.waitForTimeout(200);
		await p.click('#nuw_cus_name .nuDesignOverlay', LEFT); await p.waitForTimeout(300);
		await act('up');
		expect(+q('cus_name', 'sob_all_order') < +q('cus_code', 'sob_all_order'), 'Up: order ' + q('cus_name', 'sob_all_order') + ' / ' + q('cus_code', 'sob_all_order'));
		await p.evaluate(() => window.postMessage({ nuBuilderTabOrder: true }, window.location.origin)); await p.waitForTimeout(400);
		const badge = (id) => p.evaluate((i) => { const b = document.querySelector('#nuw_' + i + ' .nuDesignOrder'); return b ? +b.textContent : 0; }, id);
		expect(await badge('cus_name') === 1 && await badge('cus_code') === 2, 'tab order numbers after Up: ' + await badge('cus_name') + ' / ' + await badge('cus_code'));
		await act('down');
		expect(await badge('cus_name') === 2 && await badge('cus_code') === 1, 'tab order numbers after Down: ' + await badge('cus_name') + ' / ' + await badge('cus_code'));
		await p.evaluate(() => window.postMessage({ nuBuilderTabOrder: false }, window.location.origin));
		// Ctrl + A and Esc; three objects spaced vertically
		await p.click('#nuw_cus_code .nuDesignOverlay', LEFT);
		await p.locator('body').press('Control+a'); await p.waitForTimeout(200);
		expect(await nsel() >= 5, 'Ctrl+A: ' + await nsel());
		await p.locator('body').press('Escape'); await p.waitForTimeout(200);
		expect(await nsel() === 0, 'Esc');
		sql(`UPDATE zzzzsys_object SET sob_all_top = CASE sob_all_id WHEN 'cus_code' THEN 25 WHEN 'cus_name' THEN 61 ELSE 92 END WHERE sob_all_zzzzsys_form_id = '${F}' AND sob_all_id IN ('cus_code', 'cus_name', 'cus_email')`);
		await p.click('#nuDsReload'); await p.waitForSelector('#nuDsRail'); await p.waitForTimeout(800);
		for (const [i, id] of ['cus_code', 'cus_name', 'cus_email'].entries()) await p.click('#nuw_' + id + ' .nuDesignOverlay', i ? { ...LEFT, modifiers: ['Control'] } : LEFT);
		await p.waitForTimeout(300);
		await act('vertical');
		const t = ['cus_code', 'cus_name', 'cus_email'].map(id => +q(id, 'sob_all_top')), h = ['cus_code', 'cus_name'].map(id => +q(id, 'sob_all_height') || 22);
		const g1 = t[1] - (t[0] + h[0]), g2 = t[2] - (t[1] + h[1]);
		expect(Math.abs(g1 - g2) <= 2, 'Vertical spacing: ' + t.join(',') + ' gaps ' + g1 + '/' + g2);
		// box selection on an empty place
		await p.locator('body').press('Escape'); await p.waitForTimeout(200);
		const r1 = await p.locator('#nuw_cus_code').boundingBox(), r2 = await p.locator('#nuw_cus_name').boundingBox();
		const pr = await p.locator('#nuEditForm .tab-pane.active').boundingBox(), sx = pr.x + pr.width - 8, sy = r1.y - 4;
		await p.mouse.move(sx, sy); await p.mouse.down();
		await p.mouse.move(r1.x + 5, r2.y + r2.height - 2, { steps: 8 }); await p.mouse.up();
		await p.waitForTimeout(200);
		expect(await nsel() >= 2, 'box selection: ' + await nsel());
		// resizing a text area: the control follows at once
		await p.locator('body').press('Escape');
		await p.evaluate(() => window.nuSelectTab(1)); await p.waitForTimeout(300);
		const ta = () => p.evaluate(() => { const w = document.querySelector('#nuw_cus_notes'), c = w.querySelector('textarea'); return {w: w.offsetWidth, h: w.offsetHeight, cw: c.offsetWidth, ch: c.offsetHeight}; });
		await p.click('#nuw_cus_notes .nuDesignOverlay', LEFT);
		await p.locator('#nuw_cus_notes .nuDesignHandle').scrollIntoViewIfNeeded();
		const w1 = +q('cus_notes', 'sob_all_width'), h1 = +q('cus_notes', 'sob_all_height');
		const t0 = await ta(), hb = await p.locator('#nuw_cus_notes .nuDesignHandle').boundingBox();
		await p.mouse.move(hb.x + hb.width / 2, hb.y + hb.height / 2); await p.mouse.down();
		await p.mouse.move(hb.x + hb.width / 2 + 40, hb.y + hb.height / 2 + 40, { steps: 6 });
		const t1 = await ta();
		await p.mouse.up(); await p.waitForTimeout(1200);
		expect(t1.h - t0.h === 40 && t1.ch - t0.ch === 40 && t1.w - t0.w === 40, 'text area while resizing: ' + JSON.stringify([t0, t1]));
		expect(+q('cus_notes', 'sob_all_height') === h1 + 40 && +q('cus_notes', 'sob_all_width') === w1 + 40, 'text area saved: ' + q('cus_notes', 'sob_all_width') + ' x ' + q('cus_notes', 'sob_all_height'));
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally {
		execSync('mysql ' + DB + ' < ' + keep);
		fs.rmSync(keep, { force: true });
	}
};

// 0.8.523: Custom code → Global JS & CSS – files on every page of the chosen scopes, page hook nuOnPageLoad / nu:pageload with the page
// name (form pages: after nuOnLoad), never on the editor and the Update page, ?safe=1, sign-in pages only when chosen, hook name warning
T.globalcode_tabs_group = async (s) => {             // 0.8.857: switch Form pages | All pages, short tab names; a tab from the address moves the switch
	const p = s.ga;
	await open(p, 'index.php?p=globalcode');
	const shown = () => p.$$eval('#scodeTabs li:not([hidden]) .nav-link', (a) => a.map((x) => x.getAttribute('data-nu-tab') + ':' + x.textContent.trim()));
	expect((await shown()).join(',') === 'header:JavaScript,style:CSS,include:Includes', 'form tabs: ' + (await shown()).join(','));
	expect(await p.locator('#scodeSeg [data-scode-group="forms"].active').count() === 1, 'switch not on Form pages');
	await p.click('#scodeTabBtn-style'); await p.waitForTimeout(150);
	await p.click('#scodeSeg [data-scode-group="all"]'); await p.waitForTimeout(300);
	expect((await shown()).join(',') === 'gjs:JavaScript,gcss:CSS' && await p.locator('#scodePane-gjs.active').count() === 1, 'all pages: ' + (await shown()).join(','));
	// 0.8.1147: hovering a "Runs on" switch explains it
	await p.hover('label[for="scodeScope-gjs-app"]'); await p.waitForTimeout(600);
	const tip = await p.evaluate(() => (document.querySelector('.tooltip.show') || {}).textContent || '');
	expect(/start page/i.test(tip), 'Other app pages tooltip: ' + tip);
	await p.click('#scodeSeg [data-scode-group="forms"]'); await p.waitForTimeout(300);
	expect(await p.locator('#scodePane-style.active').count() === 1, 'last tab of the group not reopened');
	await open(p, 'index.php?p=globalcode#gcss'); await p.waitForTimeout(400);
	expect(await p.locator('#scodeSeg [data-scode-group="all"].active').count() === 1 && await p.locator('#scodePane-gcss.active').count() === 1, '#gcss: switch not moved');
	// phone: switch full width, tabs on one line
	await p.setViewportSize({ width: 390, height: 800 });
	try {
		await open(p, 'index.php?p=globalcode'); await p.waitForTimeout(300);
		const r = await p.evaluate(() => { const t = [...document.querySelectorAll('#scodeTabs li:not([hidden])')].map((l) => Math.round(l.getBoundingClientRect().top)); return { tops: new Set(t).size, w: document.documentElement.scrollWidth }; });
		expect(r.tops === 1 && r.w <= 390, 'phone: ' + JSON.stringify(r));
	} finally { await p.setViewportSize({ width: 1300, height: 900 }); }
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
};

T.globalcode_warn_hide = async (s) => {                // 0.8.856: the warning of Global code can be hidden (localStorage), the (i) next to the title shows it again
	const p = s.ga;
	await open(p, 'index.php?p=globalcode'); await p.evaluate(() => { try { localStorage.removeItem('nunext-scode-warn-hidden'); } catch (e) { /* */ } });
	await open(p, 'index.php?p=globalcode');
	expect(await p.isVisible('#scodeWarn') && !(await p.isVisible('#scodeWarnShow')), 'warning not shown at first');
	await p.click('#scodeWarnHide');
	expect(!(await p.isVisible('#scodeWarn')) && await p.isVisible('#scodeWarnShow'), 'not hidden');
	await open(p, 'index.php?p=globalcode');
	expect(!(await p.isVisible('#scodeWarn')) && await p.isVisible('#scodeWarnShow'), 'choice not kept');
	// 0.8.1120: a hidden warning is not drawn at all – before, it showed until the page's script ran (that script held back here)
	for (const [route, js, sel] of [['globalcode', 'nuglobalcode.js', '#scodeWarn'], ['configfile', 'nuconfigfile.js', '#cfgWarn']]) {
		await p.evaluate((k) => { try { localStorage.setItem(k, '1'); } catch (e) { /* */ } }, route === 'globalcode' ? 'nunext-scode-warn-hidden' : 'nunext-cfg-warn-hidden');
		const hold = (r) => r.abort().catch(() => {});
		await p.route('**/' + js + '*', hold);
		await p.goto(BASE + 'index.php?p=' + route, { waitUntil: 'domcontentloaded' });
		if (/reauth/.test(p.url())) { await p.unroute('**/' + js + '*', hold); continue; }
		expect(await p.locator(sel).count() === 1 && !(await p.isVisible(sel)), sel + ' flashes before the script hides it');
		await p.unroute('**/' + js + '*', hold);
		if (route === 'configfile') await p.evaluate(() => { try { localStorage.removeItem('nunext-cfg-warn-hidden'); } catch (e) { /* */ } });
	}
	p.errors.length = 0;
	await open(p, 'index.php?p=globalcode');
	expect(!(await p.isVisible('#scodeWarn')) && await p.isVisible('#scodeWarnShow'), 'still hidden with the script');
	await p.click('#scodeWarnShow');
	expect(await p.isVisible('#scodeWarn') && !(await p.isVisible('#scodeWarnShow')), '(i) does not show it');
	await open(p, 'index.php?p=globalcode');
	expect(await p.isVisible('#scodeWarn'), 'shown again after the (i), not kept');
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
};

T.custom_code = async (s) => {
	const p = s.ga;
	const del = () => sql("DELETE FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id IN ('custom_js', 'custom_css', 'custom_scope')");
	const setCm = (k, v) => p.evaluate(([k, v]) => { const ta = document.getElementById('scode-' + k); ta.nextElementSibling.CodeMirror.setValue(v); }, [k, v]);
	const openPage = async (hash) => {
		await open(p, 'index.php?p=globalcode' + (hash || ''));
		if (/p=reauth/.test(p.url())) { await p.fill('#reauthPassword', GA[1]); await Promise.all([p.waitForLoadState('networkidle'), p.click('button[type=submit]')]); await open(p, 'index.php?p=globalcode' + (hash || '')); }
	};
	const look = (u) => open(p, u).then(() => p.waitForTimeout(250)).then(() => p.evaluate(() => ({ page: document.body.dataset.nuPage, mode: document.body.dataset.nuMode || '',
		form: document.body.dataset.nuForm || '', admin: document.body.dataset.nuAdmin || '', hook: window.e2eHook || null, ev: window.e2eEv || null,
		css: getComputedStyle(document.body).getPropertyValue('--e2e-gcss').trim(), order: (window.e2eOrder || []).join('>') })));
	del();
	// 0.8.554: every tab has the editor toolbar; the editor reaches the bottom of a tall window (≥ 360 px), full screen and back
	await p.setViewportSize({ width: 1300, height: 1100 });
	try {
		await openPage('');
		const box = () => p.$eval('#scodePane-header .CodeMirror', e => { const r = e.getBoundingClientRect(); return { top: r.top, h: r.height }; });
		const b0 = await box();
		expect(b0.h >= 360 && Math.abs(b0.top + b0.h - 1100) < 40, 'editor fills the window: ' + JSON.stringify(b0));
		expect(await p.$$eval('.scodeTools', a => a.every(e => e.querySelector('.nuCtFull'))), 'toolbar on every tab');
		await p.click('#scodePane-header .nuCtFull'); await p.waitForTimeout(300);
		expect(await p.evaluate(() => document.documentElement.classList.contains('nuCodeFullOpen')), 'full screen on');
		await p.click('#scodePane-header .nuCtFull'); await p.waitForTimeout(300);
		expect(Math.abs((await box()).h - b0.h) < 2, 'height back after full screen');
		await p.click('#scodeSeg [data-scode-group="all"]'); await p.waitForTimeout(200);   // 0.8.857: tabs of the chosen group only
		await p.click('#scodeTabBtn-gcss'); await p.waitForTimeout(400);
		expect(await p.$eval('#scodePane-gcss .CodeMirror', e => e.getBoundingClientRect().height) >= 360, 'hidden tab sized when shown');
	} finally {
		await p.setViewportSize({ width: 1300, height: 900 });
	}
	try {
		await openPage('#gjs');
		expect(await p.locator('#scodePane-gjs.active').count() === 1, 'Global JS tab from the address');
		await setCm('gjs', "window.e2eOrder = [];\nfunction nuOnPageLoad(page, info) { window.e2eHook = page + '|' + (info.mode || '') + '|' + (info.form || ''); window.e2eOrder.push('page'); }\n"
			+ "document.addEventListener('nu:pageload', function (e) { window.e2eEv = e.detail.page; });\nfunction nuOnLoad() { window.e2eOrder.push('global-onload'); }");
		await p.click('#scodeTabBtn-gcss'); await p.waitForTimeout(200);
		await setCm('gcss', '<style>\nbody { --e2e-gcss: 7px; }\n</style>');   // 0.8.557: wrapped as in Form CSS – the tags are removed on save
		await Promise.all([p.waitForNavigation(), p.click('#scodeSave')]);
		expect(!/<\/?style/i.test(sql("SELECT setting_value FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id = 'custom_css'")), 'Global CSS stored with <style>');
		expect(/style> tags were removed/.test(await p.evaluate(() => [...document.querySelectorAll('.toast, .alert')].map(e => e.textContent).join(' '))), 'no note about the removed <style> tags');
		expect(/custom_js/.test(sql("SELECT GROUP_CONCAT(zzzzsys_nunext_setting_id) FROM zzzzsys_nunext_setting WHERE zzzzsys_nunext_setting_id LIKE 'custom_%'")), 'not stored');
		expect(await p.locator('.alert-warning', { hasText: 'nuOnLoad' }).count() >= 1, 'no warning about the nuBuilder hook name');
		expect(+sql("SELECT COUNT(*) FROM zzzzsys_setup WHERE set_header LIKE '%e2eHook%'") === 0, 'written into nuBuilder\'s setup');
		// the editor itself: no global code
		let r = await look('index.php?p=globalcode');
		expect(r.page === 'globalcode' && r.hook === null && r.css === '', 'editor page loads the global code: ' + JSON.stringify(r));
		// an app page: hook, event, CSS
		r = await look('index.php?p=users');
		expect(r.page === 'users' && r.hook === 'users||' && r.ev === 'users' && r.css === '7px' && r.admin === '1', 'users page: ' + JSON.stringify(r));
		r = await look('index.php?p=update');
		expect(r.page === 'update' && r.hook === null && r.css === '', 'update page: ' + JSON.stringify(r));
		r = await look('index.php?p=users&safe=1');
		expect(r.hook === null && r.css === '', 'safe mode: ' + JSON.stringify(r));
		// a form page: mode and form code; the form's own nuOnLoad wins, nuOnPageLoad comes after it
		r = await look('index.php?p=form&f=samplecustomer');
		expect(r.page === 'form' && r.mode === 'browse' && r.form === 'sample_customer' && r.hook === 'form|browse|sample_customer' && r.css === '7px', 'form page: ' + JSON.stringify(r));
		// scope: form pages off → no code there, still on other pages; sign-in pages only when switched on
		await openPage('#gjs');
		await p.locator('#scodeScope-gjs-forms').uncheck();
		await Promise.all([p.waitForNavigation(), p.click('#scodeSave')]);
		r = await look('index.php?p=form&f=samplecustomer');
		expect(r.hook === null && r.css === '', 'forms switched off: ' + JSON.stringify(r));
		const anon = await browser.newContext(); const a = await anon.newPage();
		await a.goto(BASE + 'index.php?p=login'); await a.waitForTimeout(250);
		let lg = await a.evaluate(() => ({ page: document.body.dataset.nuPage, hook: window.e2eHook || null }));
		expect(lg.page === 'login' && lg.hook === null, 'sign-in page without the scope: ' + JSON.stringify(lg));
		expect((await a.goto(BASE + 'index.php?p=globalcodefile&t=js')).status() === 403, 'file readable without a session');
		await openPage('#gcss');
		await p.locator('#scodeScope-gcss-login').check();
		expect(await p.locator('#scodeScope-gjs-login').isChecked(), 'switches not in step');
		await Promise.all([p.waitForNavigation(), p.click('#scodeSave')]);
		await a.goto(BASE + 'index.php?p=login'); await a.waitForTimeout(250);
		lg = await a.evaluate(() => ({ page: document.body.dataset.nuPage, hook: window.e2eHook || null }));
		expect(lg.hook === 'login||', 'sign-in page with the scope: ' + JSON.stringify(lg));
		await anon.close();
		expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	} finally { del(); }
};

// 0.8.524: Custom code templates – ▾ Templates on every tab inserts at the cursor (red Save), "Preview all" shows description + code
T.custom_code_templates = async (s) => {
	const p = s.ga;
	const openPage = async (hash) => {
		await open(p, 'index.php?p=globalcode' + hash);
		if (/p=reauth/.test(p.url())) { await p.fill('#reauthPassword', GA[1]); await Promise.all([p.waitForLoadState('networkidle'), p.click('button[type=submit]')]); await open(p, 'index.php?p=globalcode' + hash); }
	};
	await openPage('#gjs');
	for (const tab of ['header', 'style', 'include', 'gjs', 'gcss']) {
		if (!await p.locator('#scodePane-' + tab).count()) continue;
		expect(await p.locator(`#scodePane-${tab} .scodeTplMenu .dropdown-item`).count() >= 3, 'no templates on ' + tab);
	}
	const val = () => p.evaluate(() => document.getElementById('scode-gjs').value);
	const before = await val();
	await p.click('#scodePane-gjs .scodeTpl .dropdown-toggle');
	await p.locator('#scodePane-gjs .scodeTplMenu .dropdown-item', { hasText: /skeleton|Gerüst/ }).first().click();
	await p.waitForTimeout(200);
	expect((await val()).includes('function nuOnPageLoad(page, info)') && await p.locator('#scodeSave.nuSaveEdited').count() === 1, 'template not inserted / Save not red');
	await p.click('#scodePane-gjs .scodeTpl .dropdown-toggle');
	await p.locator('#scodePane-gjs .scodeTplMenu .dropdown-item').last().click();
	await p.waitForSelector('#scodeTplDlg.show');
	const items = await p.locator('#scodeTplList .list-group-item-action').count();
	await p.locator('#scodeTplList .list-group-item-action').nth(1).click();
	const code = await p.textContent('#scodeTplCode');
	expect(items >= 5 && code.length > 20 && (await p.textContent('#scodeTplDesc')).length > 5, 'preview dialogue: ' + items);
	await p.click('#scodeTplInsert'); await p.waitForTimeout(400);
	expect((await val()).includes(code.trim().split('\n')[0]) && !(await p.locator('#scodeTplDlg.show').count()), 'Insert from the dialogue');
	expect(before === '' || (await val()).startsWith(before.trim().split('\n')[0]), 'existing code changed');
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	await p.evaluate(() => { window.nuLeaveGuard.isDirty = () => false; });   // leave without saving (no beforeunload question)
};

// 0.8.527 / 0.8.530: API client → service user: New service user (its fields) or Existing user (Tom Select: login name, full name ·
// access level as second line, the chosen user's access level below); Existing without a user is refused, with one it is saved
T.api_client_user_select = async (s) => {
	const p = s.ga;
	await open(p, 'index.php?p=apiclients&id=new');
	expect(await p.locator('#suModeNew:checked').count() === 1 && await p.locator('.nuApiNewUser:not([hidden])').count() === 1
		&& await p.locator('.nuApiExistUser[hidden]').count() === 1, 'New service user at first, its fields shown');
	await p.click('label[for=suModeExisting]');
	expect(await p.locator('.nuApiNewUser[hidden]').count() === 1 && await p.locator('.nuApiExistUser:not([hidden])').count() === 1, 'Existing user: list shown');
	expect(await p.locator('#user_id.tomselected').count() === 1, 'service user is a Tom Select');
	await p.fill('#name', 'E2E client');
	await Promise.all([p.waitForNavigation(), p.click('button.nuBtnSave')]);
	expect(await p.locator('#user_id.is-invalid, .nuApiExistUser .invalid-feedback').count() > 0 && await p.locator('#suModeExisting:checked').count() === 1, 'existing without a user: refused, choice kept');
	await p.locator('#user_id + .ts-wrapper .ts-control').click();
	await p.keyboard.type('sample_anna');
	const opt = p.locator('.ts-dropdown .option', { hasText: 'sample_anna' }).first();
	await opt.waitFor();
	expect((await opt.locator('.small').count()) === 1, 'second line with name / access level');
	await opt.click(); await p.waitForTimeout(200);
	expect(/sample_viewer/.test(await p.textContent('#apiUserAccess')), 'access level of the chosen user: ' + await p.textContent('#apiUserAccess'));
	await Promise.all([p.waitForNavigation(), p.click('button.nuBtnSave')]);
	const anna = sql("SELECT zzzzsys_user_id FROM zzzzsys_user WHERE sus_login_name = 'sample_anna'");
	expect(sql("SELECT COUNT(*) FROM zzzzsys_nunext_api_client WHERE name = 'E2E client' AND user_id = '" + anna + "'") === '1', 'saved with the existing user');
	sql("DELETE FROM zzzzsys_nunext_api_client WHERE name = 'E2E client'");
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
};

// 0.8.528: F1 opens the documentation page of the page that is open (new tab); pages without one leave F1 alone
T.help_f1 = async (s) => {
	const p = s.ga;
	const f1 = async (path, want) => {
		await open(p, path);
		const [tab] = await Promise.all([p.context().waitForEvent('page', { timeout: 5000 }), p.keyboard.press('F1')]);
		await tab.waitForLoadState('domcontentloaded');
		const ok = /p=help/.test(tab.url()) && tab.url().endsWith('#' + want);
		await tab.close();
		expect(ok, path + ' → ' + tab.url());
	};
	await f1('index.php?p=users', 'users');
	await f1('index.php?p=form&f=samplecustomer', 'forms-use');
	await f1('index.php', 'home-page');
	await open(p, 'index.php?p=help');
	expect(await p.evaluate(() => document.body.getAttribute('data-nu-help')) === null, 'no F1 link on the help page');
	expect(await p.locator('.dropdown-menu a[href$="p=help"][target=_blank]').count() === 1, 'user menu: documentation opens in a new tab (0.8.541)');
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
};

// 0.8.536: searchable selects (Tom Select) for long lists – builder objects (lookup / sub-form / run form / report / display procedure)
// and own pages (start form, launch form, e-mail template form, cloner, dashboard widget, time zone); object ID: trimmed, checked while typing
T.searchable_selects = async (s) => {
	const p = s.ga;
	const ts = async (path, ids) => {
		await open(p, path);
		if (/p=reauth/.test(p.url())) { await p.fill('#reauthPassword', GA[1]); await Promise.all([p.waitForLoadState('networkidle'), p.click('button[type=submit]')]); await open(p, path); }
		for (const id of ids) expect(await p.locator(id + '.tomselected').count() === 1, path + ': ' + id + ' not searchable');
	};
	await ts('index.php?p=accesslevel&id=sample_editor', ['#sal_zzzzsys_form_id']);
	await ts('index.php?p=procedures&id=new', ['#sph_zzzzsys_form_id']);
	await ts('index.php?p=emailtemplates&id=new', ['#emt_form_id']);
	await ts('index.php?p=cloner&id=new', ['#clSource', '#clDest']);
	await ts('index.php?p=dashboards&id=sample_dash_country&w=new', ['#dSelect', '#dPhp']);
	await ts('index.php?p=setupwizard', ['#timezone']);
	// design mode (0.8.670, before: the builder): lookup / sub-form objects of "Sample: all objects", the object ID check
	sql("DELETE FROM zzzzsys_nunext_form_draft WHERE form_id = 'sampleall'");
	await open(p, 'index.php?p=form&f=sampleall&r=-1&design=1'); await p.waitForSelector('#nuDsRail'); await p.waitForTimeout(600);
	for (const [type, key] of [['lookup', 'sob_lookup_zzzzsys_form_id'], ['subform', 'sob_subform_zzzzsys_form_id']]) {
		const id = sql("SELECT sob_all_id FROM zzzzsys_object WHERE sob_all_zzzzsys_form_id = 'sampleall' AND sob_all_type = '" + type + "' LIMIT 1");
		if (!id) continue;
		await p.click('#nuDsRailStructure'); await p.waitForTimeout(300);
		await p.click('#nuDsTree .nuDsTreeRow[data-id="' + id + '"]'); await p.waitForTimeout(600); await p.click("#nuDsFly .btn-close");
		expect(await p.locator('#nuDsPanel select[data-key=' + key + '].tomselected').count() === 1, type + ': form select not searchable');
	}
	const idf = p.locator('#nuDsPanel input[data-key=sob_all_id]');
	await idf.fill('bad id-1'); await idf.dispatchEvent('change'); await p.waitForTimeout(200);
	expect(await idf.evaluate(e => e.classList.contains('is-invalid')), 'invalid ID marked');
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
	await p.evaluate(() => { if (window.nuLeaveGuard) window.nuLeaveGuard.isDirty = () => false; });
};

