T.settings_hint_phone = async (s) => {                // 0.8.1084: the (i) of a settings page opens its hint on phones too
	const p = s.ga;
	const ctx = await p.context().browser().newContext({ viewport: { width: 390, height: 800 }, storageState: await p.context().storageState() });
	const ph = await ctx.newPage();
	try {
		await ph.goto(BASE + 'index.php?p=configfile');
		await ph.click('button.nuInfoBtn[data-bs-target="#cfgHint"]');
		await ph.waitForTimeout(500);
		expect(await ph.isVisible('#cfgHint'), 'hint shown after the tap');
		// 0.8.1085: the warning can be hidden (×) and comes back with the ⚠ next to the title, also after a reload
		await ph.click('#cfgWarnHide');
		expect(!(await ph.isVisible('#cfgWarn')) && await ph.isVisible('#cfgWarnShow'), 'warning hidden, ⚠ shown');
		await ph.reload();
		expect(!(await ph.isVisible('#cfgWarn')) && await ph.isVisible('#cfgWarnShow'), 'stays hidden after a reload');
		await ph.click('#cfgWarnShow');
		expect(await ph.isVisible('#cfgWarn') && !(await ph.isVisible('#cfgWarnShow')), 'shown again');
	} finally { await ctx.close(); }
};

T.ui_review_h = async (s) => {                     // 0.8.1068: review H1–H6 on a phone
	const st = await s.ga.context().storageState();
	const c = await s.ga.context().browser().newContext({ locale: 'en-GB', viewport: { width: 390, height: 844 }, hasTouch: true, storageState: st });
	const p = await c.newPage(), errs = []; p.on('pageerror', (e) => errs.push(e.message));
	try {
		await open(p, 'index.php?p=procedures');
		const own = await p.evaluate(() => [...document.querySelectorAll('[data-href], tr[data-href]')].length);
		expect(/origin/.test(await p.content()), 'H5: origin filter on procedures');
		expect(!(await p.locator('text=nu_send_welcome_email_template').count()) || own >= 0, 'H5');
		const n = Number(sql("SELECT COUNT(*) FROM zzzzsys_php WHERE zzzzsys_php_id LIKE 'nu%'").trim() || 0);
		const shown = await p.evaluate(() => [...document.querySelectorAll('tr[data-href]')].filter((r) => /zzzzsys_php_id=nu|id=nu/.test(r.getAttribute('data-href'))).length);
		expect(n === 0 || shown === 0, 'H5: system procedures hidden by default ' + shown);
		await open(p, 'index.php?p=emailtemplates');
		const langs = await p.evaluate(() => document.body.innerText);
		expect(!/\bFrench\b/.test(langs), 'H5: templates in other languages hidden');
		await open(p, 'index.php?p=settings&s=general');
		expect(await p.locator('#nuSetPhSel').isVisible() && !(await p.locator('.nuSetSections').isVisible()), 'H6: section select on phones');
		await open(p, 'index.php?p=forms');
		const w = await p.evaluate(() => { const h = document.querySelector('.nuListCard > .nuListHead'); return h ? h.scrollWidth <= window.innerWidth + 1 : true; });
		expect(w, 'H3: list title bar fits');
		await open(p, 'index.php?p=users');
		const first = await p.evaluate(() => { const m = document.querySelector('.nuListCard .nuMoreMenu .dropdown-menu'); const a = m && m.querySelector('.nuPhMoreItem'); return a ? [m.firstElementChild.contains(a), a.querySelector('.bi-table, .bi-card-list') !== null] : null; });
		expect(first && first[0] && first[1], 'card / table switch first in ⋮ ' + JSON.stringify(first));
		for (const pg of ['users', 'procedures', 'access', 'reports', 'items', 'forms', 'emailtemplates', 'log', 'permissions', 'files']) {     // the switch has a visible icon in ⋮, in both states
			for (const mode of ['cards', 'table']) {
				await p.evaluate((m) => { try { localStorage.setItem('nunext-lv-phone-' + m[1], m[0]); } catch (e) {} }, [mode, pg]);
				await open(p, 'index.php?p=' + pg);
				const ok = await p.evaluate(() => { const b = document.querySelector('.nuListCard [data-lv-phone-toggle]'); if (!b) return 'none';
					const it = [...document.querySelectorAll('.nuPhMoreItem')].find((a) => a.querySelector('.nuLvPhoneToTable, .nuLvPhoneToCards'));
					if (!it) return 'noitem'; return [...it.querySelectorAll('.bi')].some((i) => getComputedStyle(i).display !== 'none'); });
				expect(ok === true || ok === 'none', 'icon of the card / table entry on ' + pg + ' (' + mode + '): ' + ok);
			}
		}
		const fine = await p.evaluate(() => matchMedia('(pointer: fine)').matches);
		expect(!fine, 'H4: touch context');
	} finally { await c.close(); }
	expect(errs.length === 0, errs.slice(0, 2).join(' | '));
};

T.translations_form = async (s) => {                     // 0.8.754: missing translations of one form in every language, AI round trip, design mode, select options
	const p = s.ga;
	const clean = () => sql("DELETE FROM zzzzsys_translate WHERE trl_translation LIKE 'E2E %'; DELETE FROM zzzzsys_nunext_log WHERE event = 'translations_ai'");
	clean();
	try {
		const U = 'index.php?p=translations&view=missing&f=samplecustomer';
		await open(p, U);
		const rows = await p.$$eval('#trlMatrix tbody tr', (r) => r.map((x) => [x.getAttribute('data-text'), x.innerText]));
		const au = rows.find((r) => r[0] === 'Australia');
		expect(au && await p.locator('#trlMatrix th[data-lang="German"]').count() === 1, 'matrix without the select option text / German: ' + JSON.stringify(rows.slice(0, 3)));
		// the prompt (JSON route, nothing stored)
		const pr = await p.evaluate(async () => {
			const f = document.getElementById('trlAiPromptForm');
			const fd = new FormData(f);
			fd.delete('ai_lang[]'); fd.append('ai_lang[]', 'German');
			return (await fetch(f.getAttribute('data-url'), {method: 'POST', body: fd, credentials: 'same-origin'})).json();
		});
		expect(pr.ok && /nunext-translate-1/.test(pr.prompt) && /"en": "Australia"/.test(pr.prompt) && /into German\./.test(pr.prompt), 'prompt: ' + JSON.stringify(pr).slice(0, 300));
		// paste an answer: two good rows, one unknown text, one unknown language
		const ans = 'Sure:\n```json\n' + JSON.stringify({format: 'nunext-translate-1', translations: {German: {Australia: 'E2E Australien', Customer: 'E2E Kunde', Nonsense: 'E2E x'}, Klingon: {Customer: 'E2E Q'}}}) + '\n```';
		await p.fill('#trlAiAnswer', ans);
		await Promise.all([p.waitForNavigation(), p.click('#trlAiCheck')]);
		const st = await p.$$eval('#trlAiPreview tbody tr', (r) => r.map((x) => x.getAttribute('data-status')).join(','));
		expect(st === 'new,new,skip,skip', 'preview statuses: ' + st);
		expect(await p.locator('.trlAiLang:checked').count() > 0, 'languages not ticked after the check');
		await Promise.all([p.waitForNavigation(), p.click('#trlAiSave')]);
		expect(+sql("SELECT COUNT(*) FROM zzzzsys_translate WHERE trl_language = 'German' AND trl_translation IN ('E2E Australien', 'E2E Kunde')") === 2, 'translations not saved');
		expect(+sql("SELECT COUNT(*) FROM zzzzsys_nunext_log WHERE event = 'translations_ai'") === 1, 'not logged');
		const cell = await p.locator('#trlMatrix tr[data-text="Australia"] td[data-lang="German"]').innerText();
		expect(/E2E Australien/.test(cell), 'matrix cell after saving: ' + cell);
		// a broken answer
		await p.fill('#trlAiAnswer', 'no json here');
		await Promise.all([p.waitForNavigation(), p.click('#trlAiCheck')]);
		expect(await p.locator('#trlAiError').count() === 1, 'no error for an answer without JSON');
		// design mode: Tools → Translations with the missing count
		await open(p, 'index.php?p=form&f=samplecustomer&r=-1&design=1');
		const dt = await p.evaluate(() => window.nuNext && window.nuNext.design && window.nuNext.design.translations);
		expect(dt && /f=samplecustomer/.test(dt.url) && dt.missing && dt.missing.German > 0, 'design client translations: ' + JSON.stringify(dt));
		// the reader's language: a fixed select option is translated, the value stays
		const u = await login('sample_ben', UPW);
		await open(u, 'index.php?p=form&f=samplecustomer&r=-1');
		const opt = await u.evaluate(() => { const o = [...document.querySelectorAll('#cus_country option')].find((x) => /Austral/.test(x.textContent)); return o ? [o.value, o.textContent] : null; });
		expect(opt && opt[1] === 'E2E Australien' && opt[0] !== 'E2E Australien', 'select option not translated: ' + JSON.stringify(opt));
		await u.context().close();
	} finally { clean(); }
	expect(p.errors.length === 0, p.errors.slice(0, 2).join(' | '));
};

T.excel_export = async (s) => {                         // 0.8.398: Export Excel of a list print view (visible columns) and of a form browse list
	const p = s.ga;
	const read = async (url) => {
		const r = await p.request.get(BASE + url);
		const buf = await r.body();
		const f = path.join(require('os').tmpdir(), 'e2e-' + Date.now() + '.xlsx');
		fs.writeFileSync(f, buf);
		try {
			return { status: r.status(), ct: r.headers()['content-type'] || '', rows: JSON.parse(execSync('python3 -', { input: "import openpyxl, json\nws = openpyxl.load_workbook(" + JSON.stringify(f) + ").worksheets[0]\nprint(json.dumps({'rows': [[str(c) if c is not None else None for c in r] for r in ws.iter_rows(values_only=True)][:5], 'bold': bool(ws['A1'].font.b), 'freeze': ws.freeze_panes, 'filter': ws.auto_filter.ref}))" }).toString()) };
		} finally { fs.rmSync(f, { force: true }); }
	};
	let r = await read('index.php?p=forms&export=xlsx');
	expect(r.status === 200 && /spreadsheetml/.test(r.ct) && r.rows.bold && r.rows.freeze === 'A2' && /^A1:/.test(r.rows.filter || ''), 'forms list as Excel: ' + JSON.stringify(r).slice(0, 300));
	const all = r.rows.rows[0].length;
	r = await read('index.php?p=forms&export=xlsx&cols=0,2');
	expect(r.rows.rows[0].length === 2 && all > 2, 'visible columns only: ' + JSON.stringify(r.rows.rows[0]));
	// the print view's button carries the visible columns
	await open(p, 'index.php?p=forms&export=print');
	await p.evaluate(() => { try { localStorage.removeItem('nunext-print-cols:forms'); } catch (e) {} });
	await open(p, 'index.php?p=forms&export=print');
	await p.locator('.nu-print-table thead th .nuColHide').nth(1).click();
	expect(/cols=0%2C2|cols=0,2/.test(await p.getAttribute('#nuXlsxButton', 'href')), 'Export Excel without the visible columns: ' + await p.getAttribute('#nuXlsxButton', 'href'));
	await p.click('#nuPrintReset');
	// form browse list (print view → Export Excel)
	await open(p, 'index.php?p=form&f=samplecustomer&print=1');
	const href = await p.getAttribute('#nuXlsxButton', 'href');
	r = await read(href);
	expect(r.status === 200 && r.rows.rows.length > 1 && r.rows.bold, 'form browse list as Excel: ' + JSON.stringify(r).slice(0, 300));
	// the Export menu (0.8.398): HTML page, CSV … (dialog), Excel – lists and form browse lists
	for (const [url, btn] of [['index.php?p=users', '#nuListExportBtn'], ['index.php?p=form&f=samplecustomer', '#nuExportButton']]) {
		await open(p, url);
		await p.click(btn); await p.waitForTimeout(300);
		const menu = p.locator(btn + ' + .dropdown-menu');
		expect(await menu.locator('.nuExpHtml').isVisible() && await menu.locator('.nuExpCsv').isVisible() && await menu.locator('.nuExpXlsx').isVisible(), url + ': Export menu');
		expect(/print/.test(await menu.locator('.nuExpHtml').getAttribute('href')) && /xlsx/.test(await menu.locator('.nuExpXlsx').getAttribute('href')), url + ': menu links');
		await menu.locator('.nuExpCsv').click(); await p.waitForTimeout(500);
		expect(await p.locator('#nuCsvDialog').isVisible(), url + ': CSV dialog');
		await p.keyboard.press('Escape'); await p.waitForTimeout(300);
	}
	// without the print right: no file
	const ben = await login('sample_ben', UPW);
	const rb = await ben.request.get(BASE + 'index.php?p=users&export=xlsx');
	expect(rb.status() === 403 || !/spreadsheetml/.test(rb.headers()['content-type'] || ''), 'Excel without the print right');
	await ben.context().close();
};

T.print_columns = async (s) => {                        // 0.8.397: print view of a list – × hides a column, Undo, Reset view, remembered
	const p = s.ga;
	await open(p, 'index.php?p=forms&export=print');
	await p.evaluate(() => { try { localStorage.removeItem('nunext-print-cols:forms'); } catch (e) {} });
	await open(p, 'index.php?p=forms&export=print');
	const vis = async () => p.locator('.nu-print-table thead th:not(.nuColHidden)').count();
	const n = await vis();
	expect(n > 2 && await p.isDisabled('#nuPrintUndo') && await p.isDisabled('#nuPrintReset'), 'start state');
	await p.locator('.nu-print-table thead th .nuColHide').nth(1).click();
	await p.locator('.nu-print-table thead th .nuColHide').nth(2).click();
	const cells = await p.evaluate(() => document.querySelector('.nu-print-table tbody tr').querySelectorAll('td:not(.nuColHidden)').length);
	expect(await vis() === n - 2 && cells === n - 2 && /2/.test(await p.textContent('#nuPrintHiddenInfo')), 'hide two columns');
	await open(p, 'index.php?p=forms&export=print');
	expect(await vis() === n - 2, 'hidden columns not remembered');
	await p.click('#nuPrintUndo');
	expect(await vis() === n - 1, 'undo');
	await p.click('#nuPrintReset');
	expect(await vis() === n && await p.isDisabled('#nuPrintUndo'), 'reset view');
};

T.list_reset = async (s) => {                           // 0.8.395: the × of a filtered list sits right of the funnel, same size
	await open(s.ga, 'index.php?p=forms&type=edit');
	const box = async (sel) => s.ga.locator(sel).boundingBox();
	const f = await box('.nuFilterToggle'), x = await box('.nuListResetBtn');
	expect(f && x && Math.abs(f.height - x.height) < 1 && Math.abs(f.width - x.width) < 2 && Math.abs(f.y - x.y) < 1 && x.x > f.x && x.x - (f.x + f.width) < 16, 'reset not next to the funnel: ' + JSON.stringify([f, x]));
	const bc = await s.ga.evaluate(() => ['.nuFilterToggle', '.nuListResetBtn'].map((q) => getComputedStyle(document.querySelector(q)).borderTopColor));
	expect(bc[0] === bc[1], 'reset border differs from the filter button: ' + bc.join(' / '));
	await Promise.all([s.ga.waitForNavigation(), s.ga.click('.nuListResetBtn')]);
	expect(!/type=/.test(s.ga.url()) && await s.ga.locator('.nuListResetBtn').count() === 0, 'reset did not clear the filter');
	await open(s.ga, 'index.php?p=forms');
	expect(await s.ga.locator('.nuListResetBtn').count() === 0, '× without search or filter');
};

