		await Promise.all([p.waitForNavigation(), p.locator('.nuColMenu button', {hasText: 'Filter'}).click()]);
		expect(/"filter":true/.test(sql(`SELECT sbr_json FROM zzzzsys_browse WHERE zzzzsys_browse_id = '${bid}'`)), 'filter saved');
